INSERT INTO public.authored_days (day_id, title, subtitle, status, rich) VALUES (1, 'Jour 1 · Le Café', 'Je voudrais — la politesse.', 'draft', $rich${"gym":"","vocabulary":[{"fr":"un café","es":"un café","example":"Je voudrais un café, s'il vous plaît.","emoji":"☕"},{"fr":"un thé","es":"un té","example":"Je prends un thé au citron.","emoji":"🍵"},{"fr":"un chocolat chaud","es":"un chocolate caliente","example":"Un chocolat chaud, s'il vous plaît.","emoji":"🍫"},{"fr":"un jus d'orange","es":"un jugo de naranja","example":"Je voudrais un jus d'orange frais.","emoji":"🍊"},{"fr":"une eau","es":"un agua","example":"Une eau plate, s'il vous plaît.","emoji":"💧"},{"fr":"du lait","es":"leche","example":"Avec un peu de lait, merci.","emoji":"🥛"},{"fr":"du sucre","es":"azúcar","example":"Sans sucre, s'il vous plaît.","emoji":"🍬"},{"fr":"une tasse","es":"una taza","example":"Vous avez une grande tasse ?","emoji":"🫖"},{"fr":"un verre","es":"un vaso","example":"Un verre d'eau, s'il vous plaît.","emoji":"🥃"},{"fr":"une cuillère","es":"una cuchara","example":"Vous avez une cuillère ?","emoji":"🥄"},{"fr":"une table","es":"una mesa","example":"Je voudrais une table pour deux.","emoji":"🪑"},{"fr":"une chaise","es":"una silla","example":"Cette chaise est libre ?","emoji":"🪑"},{"fr":"le comptoir","es":"la barra","example":"Je préfère m'asseoir au comptoir.","emoji":"🍷"},{"fr":"la carte","es":"la carta / el menú","example":"Je peux voir la carte ?","emoji":"📜"},{"fr":"un serveur","es":"un camarero","example":"Excusez-moi, monsieur le serveur !","emoji":"🤵"},{"fr":"l'addition","es":"la cuenta","example":"L'addition, s'il vous plaît !","emoji":"🧾"},{"fr":"la terrasse","es":"la terraza","example":"On peut s'asseoir en terrasse ?","emoji":"🌿"},{"fr":"sur place","es":"para tomar aquí","example":"C'est sur place ou à emporter ?","emoji":"🪑"},{"fr":"à emporter","es":"para llevar","example":"À emporter, s'il vous plaît.","emoji":"🥡"},{"fr":"une serviette","es":"una servilleta","example":"Vous avez une serviette ?","emoji":"🧻"},{"fr":"je voudrais","es":"quisiera","example":"Je voudrais un café, s'il vous plaît.","emoji":"🙏"},{"fr":"s'il vous plaît","es":"por favor (formal)","example":"Un thé, s'il vous plaît.","emoji":"✨"},{"fr":"je peux avoir…","es":"¿podría tener…?","example":"Je peux avoir un peu de lait ?","emoji":"🤲"},{"fr":"par carte","es":"con tarjeta","example":"Je peux payer par carte ?","emoji":"💳"},{"fr":"en espèces","es":"en efectivo","example":"Je paye en espèces.","emoji":"💶"},{"fr":"c'est combien ?","es":"¿cuánto es?","example":"C'est combien, le café ?","emoji":"❓"},{"fr":"ça fait combien ?","es":"¿cuánto es en total?","example":"Ça fait combien pour les deux ?","emoji":"💰"},{"fr":"la note","es":"la nota / la cuenta","example":"Je voudrais la note, s'il vous plaît.","emoji":"📝"},{"fr":"chaud / froid","es":"caliente / frío","example":"Je voudrais quelque chose de chaud.","emoji":"🔥"},{"fr":"avec / sans","es":"con / sin","example":"Un café avec du lait et sans sucre.","emoji":"➕"}],"flashQuiz":[],"grammar":[{"formula":"Je voudrais un café, s'il vous plaît.","use":"Di « Je voudrais un café, s'il vous plaît. » en lugar de « Je veux un café, s'il vous plaît. » (registro cortés)."},{"formula":"Je voudrais payer par carte.","use":"Di « Je voudrais payer par carte. » en lugar de « Je veux payer par carte. » (registro cortés)."},{"formula":"Je voudrais une table pour deux.","use":"Di « Je voudrais une table pour deux. » en lugar de « Je veux une table pour deux. » (registro cortés)."},{"formula":"Je voudrais la carte.","use":"Di « Je voudrais la carte. » en lugar de « Je veux la carte. » (registro cortés)."},{"formula":"Je voudrais un thé au citron.","use":"Di « Je voudrais un thé au citron. » en lugar de « Je veux un thé au citron. » (registro cortés)."}],"vocabGames":{"reading":[{"title":"Texte 1 · Une table pour deux","text":"Bonjour ! Je m'appelle Marie. Aujourd'hui, je vais dans un petit café à Paris avec un ami. Il y a beaucoup de monde à l'intérieur, alors je ne veux pas aller au comptoir. Le serveur arrive et je lui dis : « Bonjour monsieur, je voudrais une table pour deux, s'il vous plaît ». Le serveur répond : « Oui, bien sûr ! » et nous apporte la carte. Je regarde la carte : je voudrais quelque chose de chaud. Je demande au serveur : « Je voudrais un chocolat chaud avec du sucre et un verre d'eau, s'il vous plaît ». Après, je demande l'addition. Ça fait 6 euros. Je paye par carte.","questions":[{"q":"Où Marie ne veut-elle pas s'asseoir ?","options":["En terrasse","Au comptoir","Sur une chaise"],"answer":1},{"q":"Qu'est-ce que Marie demande au serveur avec son chocolat chaud ?","options":["Un thé au citron","Un jus d'orange","Du sucre et un verre d'eau"],"answer":2},{"q":"Comment paye-t-elle la note ?","options":["En espèces","Par carte","Elle ne paye pas"],"answer":1}]},{"title":"Texte 2 · Un café à emporter","text":"Thomas est pressé ce matin. Il entre dans le café et marche directement vers le comptoir. Il salue le serveur : « Bonjour ! ». Le serveur lui demande : « C'est sur place ou à emporter ? ». Thomas répond : « À emporter, s'il vous plaît ! ». Thomas veut un grand café. Il dit : « Je voudrais un café avec du lait, mais sans sucre ». Le serveur prépare la boisson dans une grande tasse pour emporter. Thomas demande : « C'est combien, s'il vous plaît ? ». Le serveur répond : « Ça fait 3 euros 50 ». Thomas n'a pas de carte bancaire aujourd'hui, alors il dit : « Je paye en espèces, voici 4 euros ». Le serveur lui donne la monnaie et une serviette.","questions":[{"q":"Où va Thomas dans le café ?","options":["En terrasse","Au comptoir","Il cherche une table pour deux"],"answer":1},{"q":"Comment Thomas veut-il son café ?","options":["Avec du lait et sans sucre","Chaud et avec beaucoup de sucre","Froid et sans lait"],"answer":0},{"q":"Comment Thomas paye-t-il sa boisson ?","options":["Par carte","Avec una aplicación","En espèces"],"answer":2}]}],"listening":[{"audio":"Un chocolat chaud, s'il vous plaît.","question":"¿Qué bebida ha pedido el cliente?","options":["Un café","Un thé au citron","Un chocolat chaud"],"answer":2},{"audio":"Je paye en espèces.","question":"¿Cómo va a pagar el cliente?","options":["Con tarjeta","En efectivo","No va a pagar"],"answer":1},{"audio":"C'est sur place ou à emporter ?","question":"¿Qué está preguntando el camarero?","options":["Si quiere azúcar o leche","Si es para tomar aquí o para llevar","Cuánto cuesta el pedido"],"answer":1},{"audio":"Un café avec du lait et sans sucre.","question":"¿Cómo quiere el café el cliente?","options":["Con leche y sin azúcar","Solo y con azúcar","Con leche y con azúcar"],"answer":0},{"audio":"L'addition, s'il vous plaît !","question":"¿Qué está pidiendo el cliente?","options":["La carta","Una servilleta","La cuenta"],"answer":2}],"speaking":[{"situation":"Entras al café y quieres pedir una mesa para dos personas de manera educada.","expected":"Une table pour deux, s'il vous plaît."},{"situation":"El camarero te trae el té, pero olvida la cuchara. Pídele una con educación.","expected":"Vous avez une cuillère ?"},{"situation":"Quieres pedir un jugo de naranja fresco.","expected":"Je voudrais un jus d'orange frais."},{"situation":"Estás listo para irte y llamas al camarero para pedirle la cuenta.","expected":"L'addition, s'il vous plaît !"},{"situation":"Quieres preguntarle al camarero cuánto cuesta el café.","expected":"C'est combien, le café ?"}],"writing":[{"prompt":"Traduce al francés: « Una taza grande, por favor. »","answer":"Une grande tasse, s'il vous plaît."},{"prompt":"Traduce al francés: « ¿Puedo pagar con tarjeta? »","answer":"Je peux payer par carte ?"},{"prompt":"Completa la palabra que falta: « Je préfère m'asseoir au ____ (la barra). »","answer":"comptoir"},{"prompt":"Traduce al francés: « Para llevar, por favor. »","answer":"À emporter, s'il vous plaît."},{"prompt":"Corrige el error y escríbela de forma formal para el camarero: « Une eau plate, s'il te plaît. »","answer":"Une eau plate, s'il vous plaît."}]},"clesReading":{"title":"Lecture · Politesse au café","text":"Un client entre dans la cafétéria. Il parle au serveur de manière très directe : « Je veux un café ». Le serveur est surpris parce que c'est un peu brusque. Un autre client arrive, sourit et utilise la formule correcte : « Bonjour ! Je voudrais une table pour deux, s'il vous plaît ». Le serveur répond avec joie. À la fin, le deuxième client dit poliment : « Je voudrais la note, s'il vous plaît ». C'est la forme parfaite, naturelle et éduquée en français.","questions":[{"q":"Pourquoi le serveur est-il surpris par le premier client ?","options":["Parce qu'il a demandé un thé au citron.","Parce que « Je veux » suena directo y puede resultar brusco con desconocidos.","Parce qu'il veut payer en espèces."],"answer":1},{"q":"Quelle est la formule polie utilisée par le deuxième client pour demander une table ?","options":["Je veux une table pour deux.","Je peux avoir une table pour deux.","Je voudrais une table pour deux."],"answer":2},{"q":"Quelle est la structure exacte du \"Conditionnel de Cortesía\" ?","options":["JE VEUX + sustantif","JE VOUDRAIS + sustantif","S'IL VOUS PLAÎT + verbe"],"answer":1}]},"clesGames":{"listening":[{"audio":"Je voudrais un café, s'il vous plaît.","question":"¿Cómo suena el final de la palabra 'voudrais' que acabas de escuchar?","options":["Se pronuncia la 's' final de forma fuerte.","El sonido final es suave [vud-RE] y la 's' no se pronuncia.","Suena igual que 'veux'."],"answer":1},{"audio":"Je veux la note.","question":"¿Cómo clasifica la lección esta estructura para hablar con un camarero?","options":["Formal y educada.","Informal / brusca.","Perfecta y elegante."],"answer":1},{"audio":"Je voudrais payer par carte.","question":"¿Qué está expresando el cliente con este modo verbal?","options":["Una orden directa.","Un pedido con cortesía y educación.","Una queja sobre el precio."],"answer":1},{"audio":"Je voudrais la note, s'il vous plaît.","question":"¿Qué elemento sigue inmediatamente a la palabra 'voudrais'?","options":["Un verbo en infinitivo.","Un sustantivo (la note).","Una opción de pago."],"answer":1},{"audio":"Je veux un chocolat chaud.","question":"¿Cuál sería la forma correcta y recomendada para cambiar esta frase a un tono educado?","options":["S'il vous plaît un chocolat chaud.","Je voudrais un chocolat chaud, s'il vous plaît.","Je peux un chocolat chaud."],"answer":1}],"speaking":[{"situation":"Transforma « Je veux un café » a la forma cortés recomendada para desconocidos.","expected":"Je voudrais un café, s'il vous plaît."},{"situation":"Pide una mesa para dos personas usando el Conditionnel de Cortesía. Cuida la pronunciación de voudrais.","expected":"Je voudrais une table pour deux."},{"situation":"Pide la cuenta de forma educada utilizando 'la note'.","expected":"Je voudrais la note, s'il vous plaît."},{"situation":"Indica cortésmente que quieres pagar con tarjeta.","expected":"Je voudrais payer par carte."},{"situation":"Pide elegantemente 'algo caliente'.","expected":"Je voudrais quelque chose de chaud."}],"writing":[{"prompt":"Completa: « Je ____ un café, s'il vous plaît. »","answer":"voudrais"},{"prompt":"Traduce: « Quisiera una mesa para dos. »","answer":"Je voudrais une table pour deux."},{"prompt":"Reescribe de forma educada: « Je veux la note. »","answer":"Je voudrais la note, s'il vous plaît."},{"prompt":"Completa: « Je ____ payer par carte. »","answer":"voudrais"},{"prompt":"Ordena: ( s'il vous plaît. / un chocolat chaud, / Je voudrais )","answer":"Je voudrais un chocolat chaud, s'il vous plaît."}]},"defiSteps":[{"serveur":"Très bien ! Un café. Sur place ou à emporter ?","hint":"Responde al camarero (paso 1) usando el vocabulario del día.","example":""},{"serveur":"Parfait. Avec du sucre ?","hint":"Responde al camarero (paso 2) usando el vocabulario del día.","example":""},{"serveur":"D'accord. Vous voulez quelque chose à manger ? Un croissant peut-être ?","hint":"Responde al camarero (paso 3) usando el vocabulario del día.","example":""},{"serveur":"Très bien. Ça fait 4,50 euros. Vous payez comment ?","hint":"Responde al camarero (paso 4) usando el vocabulario del día.","example":""},{"serveur":"Parfait, merci ! Bonne journée et à bientôt au café !","hint":"Responde al camarero (paso 5) usando el vocabulario del día.","example":""}],"defiCriteria":["Saluda y usa fórmulas de cortesía apropiadas al contexto.","Emplea el vocabulario clave del día (Le Café).","Aplica la estructura gramatical del día correctamente.","Responde a las preguntas del interlocutor sin cambiar al español.","Pide aclaración o repetición si no entiende algo.","Cierra la interacción con una despedida adecuada."],"tutor":{"role":"serveuse en un café parisino; el alumno es un cliente que acaba de sentarse","opener_fr":"Bonjour ! Bienvenue au café Liberté. Vous désirez ?","opener_es":"¡Hola! Bienvenido al café Liberté. ¿Qué desea?","objectives":["Saluda y pide una bebida con cortesía (« Je voudrais… »)","Pide algo de comer","Pide la cuenta y despídete"],"topic":"Au café — pedir bebidas y comida con cortesía"},"meta":{"label":"Jour 1 · Le Café","headTitle":"Jour 1 · Le Café — Liberté","headDesc":"Jour 1 · Le Café: lección completa del programa Liberté.","week":1,"weekEmoji":"🗼","intro":"Bienvenue au Jour 1 ! Ton premier café parisien. Respire, tu es prêt.","introSub":"Ton premier café parisien.","clesSub":"Je voudrais — la politesse.","defiTitle":"Le Café","defiSubtitle":"Roleplay con el camarero: pide tu primer café en francés.","defiAvatar":"🗼"}}$rich$::jsonb)
ON CONFLICT (day_id) DO NOTHING;
INSERT INTO public.authored_days (day_id, title, subtitle, status, rich) VALUES (2, 'Jour 2 · Retour au café', '4 structures pour choisir & décrire.', 'draft', $rich${"gym":"","vocabulary":[{"fr":"un expresso","es":"un espresso","example":"Je voudrais un expresso, s'il vous plaît.","emoji":"☕"},{"fr":"un cappuccino","es":"un capuchino","example":"Je prends un cappuccino avec du lait chaud.","emoji":"🥛"},{"fr":"décaféiné","es":"descafeinado","example":"Je préfère un café décaféiné le soir.","emoji":"🌙"},{"fr":"fort / léger","es":"fuerte / suave","example":"Pas trop fort — je préfère un café léger.","emoji":"💪"},{"fr":"grand / petit","es":"grande / pequeño","example":"Un grand cappuccino, s'il vous plaît.","emoji":"📏"},{"fr":"une bouteille","es":"una botella","example":"Une bouteille d'eau gazeuse, s'il vous plaît.","emoji":"🍾"},{"fr":"de la glace","es":"hielo","example":"Je voudrais de la glace avec mon eau.","emoji":"🧊"},{"fr":"une paille","es":"una pajita","example":"Est-ce que je peux avoir une paille ?","emoji":"🥤"},{"fr":"un croissant","es":"un croissant","example":"Je vais essayer le croissant du jour.","emoji":"🥐"},{"fr":"un pain au chocolat","es":"un pain au chocolat","example":"C'est fait maison, le pain au chocolat ?","emoji":"🍫"},{"fr":"une tarte","es":"una tarta","example":"Je voudrais une part de tarte aux pommes.","emoji":"🥧"},{"fr":"un gâteau","es":"un pastel","example":"Qu'est-ce que vous recommandez comme gâteau ?","emoji":"🍰"},{"fr":"une part","es":"una porción","example":"Je vais essayer une part de gâteau, merci.","emoji":"🍽️"},{"fr":"fait maison","es":"casero/a","example":"C'est fait maison ? C'est excellent !","emoji":"🏠"},{"fr":"du jour","es":"del día","example":"C'est la spécialité du jour ?","emoji":"📅"},{"fr":"la spécialité","es":"la especialidad","example":"Quelle est la spécialité du café ?","emoji":"⭐"},{"fr":"recommander","es":"recomendar","example":"Qu'est-ce que vous recommandez ?","emoji":"👉"},{"fr":"essayer","es":"probar","example":"Je vais essayer ça, merci !","emoji":"🧪"},{"fr":"payer","es":"pagar","example":"Je peux payer maintenant ?","emoji":"💳"},{"fr":"attendre","es":"esperar","example":"Je dois attendre longtemps ?","emoji":"⏳"},{"fr":"le service","es":"el servicio","example":"Le service est compris ?","emoji":"🤵"},{"fr":"le pourboire","es":"la propina","example":"Je laisse un pourboire — c'était délicieux !","emoji":"🪙"},{"fr":"rendre la monnaie","es":"dar el cambio","example":"Vous pouvez me rendre la monnaie ?","emoji":"💶"},{"fr":"un reçu","es":"un recibo","example":"Je peux avoir un reçu, s'il vous plaît ?","emoji":"🧾"},{"fr":"une commande","es":"un pedido","example":"J'ai passé ma commande — merci !","emoji":"📝"},{"fr":"Bonne journée !","es":"¡Buen día!","example":"Merci beaucoup ! Bonne journée !","emoji":"🌞"},{"fr":"doux / sucré","es":"dulce / azucarado","example":"C'est sucré ? Je préfère quelque chose de doux.","emoji":"🍬"},{"fr":"la formule","es":"el menú del día","example":"La formule du jour, c'est combien ?","emoji":"🍱"},{"fr":"le terminal","es":"el terminal de pago","example":"Je peux utiliser le terminal, s'il vous plaît ?","emoji":"🖥️"},{"fr":"savoureux","es":"sabroso","example":"C'est savoureux ! Vraiment délicieux.","emoji":"😋"}],"flashQuiz":[{"emoji":"☕","concept":"taza de espresso","options":["un expresso","un cappuccino","une tarte"],"answer":0},{"emoji":"🥛","concept":"cappuccino con espuma","options":["un cappuccino","un expresso","un croissant"],"answer":0},{"emoji":"🍾","concept":"botella de agua","options":["une bouteille","de la glace","un reçu"],"answer":0},{"emoji":"🧊","concept":"cubitos de hielo","options":["de la glace","une paille","le pourboire"],"answer":0},{"emoji":"🥤","concept":"pajita","options":["une paille","une bouteille","un gâteau"],"answer":0},{"emoji":"🥐","concept":"croissant","options":["un croissant","un pain au chocolat","une tarte"],"answer":0},{"emoji":"🍫","concept":"pain au chocolat","options":["un pain au chocolat","un croissant","une part"],"answer":0},{"emoji":"🥧","concept":"tarta","options":["une tarte","un gâteau","une part"],"answer":0},{"emoji":"🍰","concept":"pastel","options":["un gâteau","une tarte","un croissant"],"answer":0},{"emoji":"🍽️","concept":"porción de pastel en un plato","options":["une part","un gâteau","une tarte"],"answer":0},{"emoji":"🧾","concept":"recibo / ticket","options":["un reçu","une commande","le terminal"],"answer":0},{"emoji":"📝","concept":"comanda / pedido en libreta","options":["une commande","un reçu","le pourboire"],"answer":0},{"emoji":"🪙","concept":"moneda / propina","options":["le pourboire","le terminal","un reçu"],"answer":0},{"emoji":"🖥️","concept":"datáfono / terminal de pago","options":["le terminal","le pourboire","une commande"],"answer":0},{"emoji":"🍱","concept":"menú del día","options":["la formule","la spécialité","du jour"],"answer":0}],"grammar":[{"formula":"JE PRÉFÈRE + sustantivo/adjetivo","use":"Expresar preferencias personales de forma natural y segura."},{"formula":"QU'EST-CE QUE VOUS RECOMMANDEZ ? (+ comme + sustantivo)","use":"Pedir una recomendación al serveur, siendo específico."},{"formula":"JE VAIS ESSAYER + sustantivo","use":"Expresar una decisión inmediata (\"voy a probar\")."},{"formula":"C'EST + adjectif","use":"Describir o preguntar sabor, origen o cualidad (fait maison, fort, savoureux…)."}],"vocabGames":{"reading":[{"title":"Texte · Clara et le gâteau du jour","text":"Clara entre dans le café. Elle regarde la vitrine et voit des croissants, des pains au chocolat et un gâteau au chocolat. Elle demande au serveur : « C'est fait maison, le gâteau ? » Le serveur répond : « Oui, c'est la spécialité du jour ! » Clara sourit et dit : « Je vais essayer une part, s'il vous plaît. » Elle commande aussi une bouteille d'eau avec de la glace. À la fin, elle demande : « Le service est compris ? » Le serveur répond : « Oui, madame. Bonne journée ! »","questions":[{"q":"¿Qué pregunta Clara sobre el gâteau?","options":["Si es la especialidad de la semana.","Si es fait maison.","Si es grand o petit."],"answer":1},{"q":"¿Qué decide hacer Clara después de escuchar al serveur?","options":["Pedir un cappuccino.","Preguntar el precio.","Essayer une part de gâteau."],"answer":2},{"q":"¿Qué pide Clara además del gâteau?","options":["Un croissant et un café décaféiné.","Une bouteille d'eau avec de la glace.","Un pain au chocolat et une paille."],"answer":1}]}],"listening":[{"audio":"Je voudrais un expresso, pas trop fort.","question":"¿Qué tipo de café está pidiendo esta persona?","options":["Un café muy fuerte e intenso.","Un espresso suave, sin demasiada intensidad.","Un cappuccino con leche."],"answer":1},{"audio":"C'est fait maison, la tarte ?","question":"¿Qué está preguntando el cliente?","options":["Si la tarta es del día.","Si la tarta es casera.","Si la tarta es dulce o suave."],"answer":1},{"audio":"Je vais essayer une part de gâteau du jour.","question":"¿Qué está expresando el cliente?","options":["Que ya probó el pastel y le gustó.","Que quiere probar una porción del pastel del día.","Que prefiere no comer postre hoy."],"answer":1},{"audio":"Vous pouvez me rendre la monnaie, s'il vous plaît ?","question":"¿Qué está pidiendo el cliente?","options":["Un recibo para su pedido.","El terminal de pago.","El cambio de su pago."],"answer":2},{"audio":"Le service est compris ?","question":"¿Sobre qué está preguntando?","options":["Si el Wi-Fi está incluido.","Si la propina ya está incluida en la cuenta.","Si puede pedir más café sin costo."],"answer":1}],"speaking":[{"situation":"El camarero pregunta si quieres tu café fort o léger. Respóndele que lo prefieres léger.","expected":"Je préfère un café léger."},{"situation":"Ves un gâteau delicioso y quieres saber si es casero.","expected":"C'est fait maison, le gâteau ?"},{"situation":"Decides pedir una porción de tarta, de manera educada.","expected":"Je voudrais une part de tarte, s'il vous plaît."},{"situation":"Quieres asegurarte de que el servicio está incluido.","expected":"Le service est compris ?"},{"situation":"Al salir, despídete del camarero de forma natural.","expected":"Merci beaucoup ! Bonne journée !"}],"writing":[{"prompt":"Completa: « Je voudrais un café ______ — pas trop fort. »","answer":"léger"},{"prompt":"Traduce: '¿Es casero el croissant?'","answer":"C'est fait maison, le croissant ?"},{"prompt":"Corrige: « Je vais manger une morceau de tarte. »","answer":"Je vais essayer une part de tarte."},{"prompt":"Completa: « Vous pouvez me ______ ______, s'il vous plaît ? »","answer":"rendre la monnaie"},{"prompt":"Ordena: [ du jour / C'est / la spécialité / ? ]","answer":"C'est la spécialité du jour ?"}]},"clesReading":{"title":"Lecture · Sophie et la tarte aux pommes","text":"Sophie entre dans le café et s'assoit. Le serveur arrive. Sophie lui demande : « Qu'est-ce que vous recommandez comme gâteau aujourd'hui ? » Le serveur répond avec enthousiasme : « La tarte aux pommes — c'est fait maison ! » Sophie demande : « C'est sucré ? » Le serveur dit : « Non, c'est doux et savoureux ! » Sophie sourit : « Parfait ! Je préfère quelque chose de léger. Je vais essayer une part de tarte, s'il vous plaît. » Après, elle dit : « C'est vraiment savoureux ! Vous pouvez me rendre la monnaie ? Et je peux avoir un reçu ? » Le serveur répond : « Bien sûr ! Bonne journée, madame ! »","questions":[{"q":"¿Qué estructura usa Sophie para pedir una recomendación?","options":["Je voudrais + sustantivo.","Qu'est-ce que vous recommandez + comme + sustantivo.","Je préfère + adjetivo."],"answer":1},{"q":"¿Qué estructura usa para expresar que va a probar la tarta?","options":["Je préfère une part de tarte.","Je voudrais essayer la tarte.","Je vais essayer une part de tarte."],"answer":2},{"q":"¿Qué estructura usa para describir que el sabor es muy bueno?","options":["Je préfère + adjectif.","C'est + adjectif (savoureux).","Qu'est-ce que + adjectif."],"answer":1}]},"clesGames":{"listening":[{"audio":"Je préfère un café léger, pas trop fort.","question":"¿Qué estructura usa?","options":["Je voudrais + sustantivo (Día 1).","Je préfère + adjetivo.","Je vais essayer + sustantivo."],"answer":1},{"audio":"Qu'est-ce que vous recommandez comme gâteau ?","question":"¿Para qué se usa?","options":["Para pedir algo educadamente.","Para pedir una recomendación al serveur.","Para describir el sabor."],"answer":1},{"audio":"Je vais essayer le croissant du jour.","question":"¿Qué indica « Je vais + infinitif » ?","options":["Una acción que ya ocurrió.","Una preferencia habitual.","Una decisión o intención inmediata."],"answer":2},{"audio":"C'est fait maison ? C'est savoureux ?","question":"¿Qué estructura se usa?","options":["C'est + adjectif / expression.","Je préfère + adjectif.","Qu'est-ce que + verbe."],"answer":0},{"audio":"Je préfère un grand cappuccino, s'il vous plaît.","question":"¿Qué adjetivo de tamaño usa?","options":["léger","décaféiné","grand"],"answer":2}],"speaking":[{"situation":"El serveur pregunta qué café prefieres (suave y pequeño), usando JE PRÉFÈRE.","expected":"Je préfère un café léger et petit."},{"situation":"Hay varios pasteles y no sabes cuál elegir. Pide una recomendación.","expected":"Qu'est-ce que vous recommandez comme gâteau ?"},{"situation":"El serveur recomienda la tarte du jour. Acepta y dile que la probarás (JE VAIS ESSAYER).","expected":"Je vais essayer une part de tarte du jour, s'il vous plaît."},{"situation":"Pruebas el croissant y está delicioso. Dilo con C'EST + adjectif.","expected":"C'est délicieux ! C'est vraiment savoureux !"},{"situation":"Antes de pagar, pregunta si el servicio está incluido.","expected":"Le service est compris ?"}],"writing":[{"prompt":"Completa: « Je ______ un café décaféiné, pas trop fort. »","answer":"préfère"},{"prompt":"Escribe: '¿Qué café recomienda?'","answer":"Qu'est-ce que vous recommandez comme café ?"},{"prompt":"Transforma con JE VAIS ESSAYER: 'Quiero probar una porción del gâteau du jour.'","answer":"Je vais essayer une part de gâteau du jour."},{"prompt":"Corrige: « C'est bon ? C'est une spécialité de la maison ? »","answer":"C'est bon ? C'est fait maison ?"},{"prompt":"Ordena: [ recommandez / Qu'est-ce que / comme tarte / vous / ? ]","answer":"Qu'est-ce que vous recommandez comme tarte ?"}]},"defiSteps":[{"serveur":"Ah, bonjour ! Vous êtes de retour ! Votre table habituelle ?","hint":"Saluda a Marie con calidez y reconoce que ya es tu segundo día.","example":"Bonjour Marie ! Oui, avec plaisir. Merci de vous souvenir de moi !"},{"serveur":"Alors, un café comme hier ?","hint":"Pide tu café indicando fort/léger y grand/petit.","example":"Je voudrais un grand café léger, s'il vous plaît."},{"serveur":"Et pour manger, quelque chose avec ?","hint":"Usa la estructura exacta del día para pedir una recomendación.","example":"Qu'est-ce que vous recommandez comme gâteau ?"},{"serveur":"La tarte aux pommes du jour, elle est excellente !","hint":"Pregunta si es fait maison.","example":"C'est fait maison, la tarte ?"},{"serveur":"Oui, tout est fait maison ici.","hint":"Decide probarla usando « Je vais essayer… ».","example":"Alors je vais essayer une part de tarte, s'il vous plaît."},{"serveur":"Voilà, madame. Bon appétit !","hint":"Comenta el sabor con « C'est + adjectif » (délicieux, savoureux, léger…).","example":"C'est délicieux ! C'est vraiment savoureux et léger."},{"serveur":"Content que ça vous plaise !","hint":"Pregunta si debes esperar mucho y si el servicio está incluido.","example":"Je dois attendre longtemps ? Et le service est compris ?"},{"serveur":"Non, c'est prêt. Ça fait 8 euros 50.","hint":"Paga, pide el cambio o un reçu, y despídete con « Bonne journée ! ».","example":"Je paye par carte. Je peux avoir un reçu ? Merci ! Bonne journée !"}],"defiCriteria":["Saluda y usa fórmulas de cortesía apropiadas al contexto.","Emplea el vocabulario clave del día (Retour au café).","Aplica la estructura gramatical del día correctamente.","Responde a las preguntas del interlocutor sin cambiar al español.","Pide aclaración o repetición si no entiende algo.","Cierra la interacción con una despedida adecuada."],"tutor":{"role":"serveuse en un restaurante; el alumno no sabe qué elegir","opener_fr":"Bonsoir ! Voici la carte. Qu'est-ce que vous préférez : viande ou poisson ?","opener_es":"¡Buenas noches! Aquí está la carta. ¿Qué prefiere: carne o pescado?","objectives":["Di qué prefieres (« Je préfère… »)","Pide una recomendación (« Qu'est-ce que vous recommandez ? »)","Decide qué probar (« Je vais essayer… »)"],"topic":"Au restaurant — preferencias y recomendaciones"},"meta":{"label":"Jour 2 · Retour au café","headTitle":"Jour 2 · Retour au café — Liberté","headDesc":"Jour 2 · Retour au café: lección completa del programa Liberté.","week":1,"weekEmoji":"🗼","intro":"Bienvenue au Jour 2 ! De retour au café. Respire, tu es prêt.","introSub":"De retour au café.","clesSub":"4 structures pour choisir & décrire.","defiTitle":"Retour au café","defiSubtitle":"Ma première vraie conversation au café.","defiAvatar":"🗼"}}$rich$::jsonb)
