INSERT INTO public.authored_days (day_id, title, subtitle, status, rich) VALUES (3, 'Jour 3 · La Boulangerie', 'Quantités et politesse à la boulangerie.', 'draft', $rich${"gym":"","vocabulary":[{"fr":"une baguette","es":"una baguette","example":"Je voudrais une baguette bien cuite, s'il vous plaît.","emoji":"🥖"},{"fr":"du pain","es":"pan","example":"Vous avez du pain frais ?","emoji":"🍞"},{"fr":"du pain complet","es":"pan integral","example":"Je prends du pain complet, s'il vous plaît.","emoji":"🌾"},{"fr":"du pain de campagne","es":"pan rústico / de campo","example":"Vous avez du pain de campagne frais ?","emoji":"🥯"},{"fr":"une brioche","es":"una brioche","example":"Je voudrais une petite brioche — elle est fraîche ?","emoji":"🍥"},{"fr":"une boulangerie","es":"una panadería","example":"La boulangerie est le coeur du quartier.","emoji":"🏪"},{"fr":"le boulanger","es":"el panadero","example":"Le boulanger prépare le pain depuis cinq heures du matin.","emoji":"👨‍🍳"},{"fr":"une viennoiserie","es":"bollería (croissants, etc.)","example":"Quelle belle vitrine de viennoiseries !","emoji":"🥐"},{"fr":"le plateau","es":"la bandeja","example":"Sophie pose le pain sur le plateau.","emoji":"🍽️"},{"fr":"croustillant(e)","es":"crujiente","example":"C'est croustillant ou moelleux ?","emoji":"✨"},{"fr":"moelleux","es":"esponjoso / suave","example":"La brioche est vraiment moelleuse !","emoji":"☁️"},{"fr":"frais / fraîche","es":"fresco / recién hecho","example":"Le pain est frais ? Il sort du four ?","emoji":"🌿"},{"fr":"chaud","es":"caliente","example":"Le pain sort du four — il est encore chaud.","emoji":"🔥"},{"fr":"bien cuit","es":"bien cocido","example":"Je voudrais une baguette bien cuite.","emoji":"🍞"},{"fr":"doré","es":"dorado","example":"Regardez cette baguette — bien dorée, parfaite !","emoji":"🟡"},{"fr":"une tranche","es":"una rebanada","example":"Je voudrais deux tranches de pain de campagne.","emoji":"🍞"},{"fr":"tranché","es":"rebanado","example":"Je prends un demi-pain, tranché, s'il vous plaît.","emoji":"🔪"},{"fr":"entier","es":"entero","example":"Je voudrais la baguette entière.","emoji":"🥖"},{"fr":"un demi","es":"una mitad","example":"Un demi-pain, c'est parfait pour moi.","emoji":"½"},{"fr":"un paquet","es":"un paquete","example":"Je prends un paquet de biscuits.","emoji":"📦"},{"fr":"un sachet","es":"una bolsita","example":"Un sachet de graines, s'il vous plaît.","emoji":"🛍️"},{"fr":"un quart","es":"un cuarto","example":"Un quart de baguette — juste un peu.","emoji":"¼"},{"fr":"le prix","es":"el precio","example":"Quel est le prix de la brioche ?","emoji":"🏷️"},{"fr":"combien coûte","es":"¿cuánto cuesta?","example":"Combien coûte le pain de campagne ?","emoji":"❓"},{"fr":"la monnaie","es":"el cambio / la moneda","example":"Vous pouvez me rendre la monnaie ?","emoji":"💶"},{"fr":"emporter","es":"llevar / para llevar","example":"Je vais emporter, s'il vous plaît.","emoji":"🛒"},{"fr":"une commande","es":"un pedido","example":"J'ai une commande — une baguette et une brioche.","emoji":"📝"},{"fr":"C'est tout ?","es":"¿Es todo?","example":"C'est tout ? — Oui, merci, c'est tout.","emoji":"✅"},{"fr":"Autre chose ?","es":"¿Algo más?","example":"Autre chose ? — Non, c'est parfait, merci.","emoji":"➕"},{"fr":"le ticket de caisse","es":"el ticket de caja","example":"Je peux avoir le ticket de caisse, s'il vous plaît ?","emoji":"🧾"}],"flashQuiz":[{"emoji":"🥖","concept":"baguette","options":["une baguette","du pain","une brioche"],"answer":0},{"emoji":"🍞","concept":"barra de pan genérica","options":["du pain","une baguette","du pain complet"],"answer":0},{"emoji":"🌾","concept":"pan integral (con semillas)","options":["du pain complet","du pain","du pain de campagne"],"answer":0},{"emoji":"🥯","concept":"pan rústico / de campo","options":["du pain de campagne","du pain complet","une baguette"],"answer":0},{"emoji":"🍥","concept":"brioche","options":["une brioche","une viennoiserie","une baguette"],"answer":0},{"emoji":"🏪","concept":"fachada de panadería","options":["une boulangerie","le boulanger","le plateau"],"answer":0},{"emoji":"👨‍🍳","concept":"panadero con delantal","options":["le boulanger","une boulangerie","le plateau"],"answer":0},{"emoji":"🥐","concept":"croissant / bollería","options":["une viennoiserie","une brioche","une baguette"],"answer":0},{"emoji":"🍽️","concept":"bandeja de madera","options":["le plateau","le boulanger","une boulangerie"],"answer":0},{"emoji":"🍞","concept":"rebanada de pan","options":["une tranche","un quart","un demi"],"answer":0},{"emoji":"📦","concept":"paquete / bolsa cerrada","options":["un paquet","un sachet","un quart"],"answer":0},{"emoji":"🛍️","concept":"bolsita pequeña","options":["un sachet","un paquet","une tranche"],"answer":0},{"emoji":"¼","concept":"un cuarto de baguette","options":["un quart","un demi","une tranche"],"answer":0},{"emoji":"💶","concept":"monedas / cambio","options":["la monnaie","le prix","le ticket de caisse"],"answer":0},{"emoji":"🧾","concept":"ticket / recibo","options":["le ticket de caisse","la monnaie","le prix"],"answer":0}],"grammar":[{"formula":"JE VOUDRAIS + cantidad + nombre + adjetivo","use":"Pedir con precisión: cantidad, producto y cómo se quiere."},{"formula":"Adjetivos de textura (concordancia)","use":"croustillant/e · frais/fraîche · moelleux (invariable) · bien cuit/e."},{"formula":"COMBIEN COÛTE / COMBIEN COÛTENT","use":"Preguntar el precio — singular: coûte · plural: coûtent."},{"formula":"Cierre de compra","use":"C'est tout · Autre chose · emporter · ticket de caisse — cerrar como un parisino."}],"vocabGames":{"reading":[{"title":"Texte · Lucie à la boulangerie","text":"Lucie entre dans la boulangerie. Elle voit des baguettes bien dorées dans la vitrine. Elle demande à Sophie, la boulangère : « Vous avez du pain de campagne frais ? » Sophie répond : « Oui ! Il sort du four — il est encore chaud et croustillant ! » Lucie demande : « Combien coûte le pain entier ? » Sophie dit : « Deux euros cinquante. » Lucie réfléchit : « Je prends un demi-pain, tranché, s'il vous plaît. » Sophie prépare la commande et demande : « Autre chose ? » Lucie ajoute : « Une petite brioche, s'il vous plaît. C'est tout ! » Elle paye et demande le ticket de caisse. « Merci ! Je vais emporter. Bonne journée ! »","questions":[{"q":"¿Cómo describe Sophie el pan de campagne?","options":["Frío y esponjoso.","Aún caliente y crujiente, recién salido del horno.","Dorado pero muy bien cocido."],"answer":1},{"q":"¿Qué cantidad de pan elige Lucie?","options":["Un pain entier.","Dos tranches de pan.","Un demi-pain, tranché."],"answer":2},{"q":"¿Qué pide Lucie además del pan?","options":["Une baguette bien cuite.","Une petite brioche.","Un paquet de biscuits."],"answer":1}]}],"listening":[{"audio":"Je voudrais une baguette bien cuite, s'il vous plaît.","question":"¿Qué cocción pide?","options":["Pálida y suave.","Bien cocida, más oscura y crujiente.","A medio cocer."],"answer":1},{"audio":"C'est croustillant ou moelleux, le pain de campagne ?","question":"¿Sobre qué pregunta?","options":["Precio y tamaño.","Si es para llevar.","La textura — crujiente o esponjosa."],"answer":2},{"audio":"Je prends un demi-pain, tranché.","question":"¿Qué cantidad y presentación pide?","options":["Pan entero sin rebanar.","Una rebanada sola.","La mitad del pan, cortado en rebanadas."],"answer":2},{"audio":"Combien coûtent les brioches ?","question":"¿Por qué « coûtent » y no « coûte » ?","options":["Es un error.","« Coûtent » (plural) para las brioches.","Depende solo del artículo."],"answer":1},{"audio":"C'est tout, merci ! Je vais emporter.","question":"¿Qué comunica el cliente?","options":["Que no quiere nada más y se lleva el pedido.","Que quiere más pan y comerá ahí.","Que quiere el ticket y el cambio."],"answer":0}],"speaking":[{"situation":"Ves unas baguettes perfectas. Pregunta si tienen alguna bien cocida.","expected":"Vous avez une baguette bien cuite ?"},{"situation":"Sophie te muestra el pain de campagne. Pregunta si es crujiente o esponjoso.","expected":"C'est croustillant ou moelleux ?"},{"situation":"El pain de campagne cuesta 2,50 el entero. Decide llevar la mitad, rebanado.","expected":"Je prends un demi-pain, tranché, s'il vous plaît."},{"situation":"Quieres saber cuánto cuesta la brioche.","expected":"Combien coûte la brioche ?"},{"situation":"Ya tienes todo. Dile que es todo y que te lo llevas.","expected":"C'est tout, merci ! Je vais emporter."}],"writing":[{"prompt":"Completa: « La baguette est ______ — elle est parfaite ! » (crujiente)","answer":"croustillante"},{"prompt":"Traduce: '¿Cuánto cuesta el pan de campo?'","answer":"Combien coûte le pain de campagne ?"},{"prompt":"Escribe cómo pides media baguette rebanada, educadamente.","answer":"Je voudrais un demi-pain, tranché, s'il vous plaît."},{"prompt":"Responde a « Autre chose ? » que no, que es todo y te lo llevas.","answer":"Non, c'est tout, merci ! Je vais emporter."},{"prompt":"Ordena: [ le ticket / Je peux avoir / de caisse / ? ]","answer":"Je peux avoir le ticket de caisse ?"}]},"clesReading":{"title":"Lecture · Marc à la boulangerie","text":"Marc entre dans la boulangerie. Il demande : « Combien coûte la baguette tradition ? » Sophie répond : « Un euro vingt. » Marc dit : « Je voudrais deux baguettes bien cuites, s'il vous plaît. » Sophie demande : « Entières ou tranchées ? » Marc : « Entières, merci. Et vous avez du pain de campagne ? C'est croustillant ? » Sophie : « Oui — la croûte est croustillante mais la mie est moelleuse. » Marc : « Parfait ! Je prends un demi-pain, tranché. » Sophie sourit : « Autre chose ? » Marc : « Non, c'est tout. Je vais emporter. Je peux avoir le ticket de caisse, s'il vous plaît ? »","questions":[{"q":"¿Qué estructura usa Marc para pedir las baguettes con precisión?","options":["Je prends + nombre.","Je voudrais + cantidad + nombre + adjetivo.","Vous avez + nombre + adjetivo."],"answer":1},{"q":"Sophie dice « croustillante » con -e final. ¿Por qué?","options":["Es invariable.","Porque « la croûte » es femenino.","Es un error."],"answer":1},{"q":"¿Qué tres expresiones usa Marc para cerrar la compra?","options":["C'est tout · emporter · ticket de caisse.","Autre chose · combien coûte · bonne journée.","C'est tout · je préfère · merci."],"answer":0}]},"clesGames":{"listening":[{"audio":"Je voudrais un demi-pain de campagne, tranché, s'il vous plaît.","question":"¿Qué elementos incluye?","options":["Solo el nombre — falta cantidad.","Cantidad + nombre + forma — pedido completo.","Solo el adjetivo de textura."],"answer":1},{"audio":"Combien coûtent les brioches ? Et combien coûte le pain entier ?","question":"¿Por qué el cambio « coûtent » / « coûte » ?","options":["Es un error.","Depende del número: plural « coûtent », singular « coûte ».","Depende solo del artículo."],"answer":1},{"audio":"Une baguette croustillante et un pain moelleux, s'il vous plaît.","question":"¿Diferencia de concordancia?","options":["Ninguna, ambos invariables.","« Croustillante » concuerda con « baguette » (femenino); « moelleux » no cambia.","Ambos concuerdan igual."],"answer":1},{"audio":"C'est tout, merci. Je vais emporter.","question":"¿Qué confirma el cliente?","options":["Que quiere algo más y pagará con tarjeta.","Que el pedido está completo y se lo lleva.","Que quiere el ticket y volverá mañana."],"answer":1},{"audio":"Autre chose ? — Non, c'est parfait, merci !","question":"¿Función de « Autre chose ? » ?","options":["Decir « buen provecho ».","Preguntar si pagará ahora.","Preguntar si el cliente quiere algo más antes de cerrar."],"answer":2}],"speaking":[{"situation":"Pide una baguette bien cocida y entera (JE VOUDRAIS + cantidad + nombre + adjetivo).","expected":"Je voudrais une baguette entière, bien cuite, s'il vous plaît."},{"situation":"Pregunta si el pain de campagne es crujiente (concordancia con « pain », masculino).","expected":"C'est croustillant, le pain de campagne ?"},{"situation":"Pregunta el precio de varias brioches (plural).","expected":"Combien coûtent les brioches ?"},{"situation":"Pregunta el precio de una sola baguette tradition (singular).","expected":"Combien coûte la baguette tradition ?"},{"situation":"Cierra la compra: es todo, te lo llevas, pide el ticket.","expected":"C'est tout, merci. Je vais emporter. Je peux avoir le ticket de caisse ?"}],"writing":[{"prompt":"Construye: JE VOUDRAIS + un demi + pain de campagne + tranché.","answer":"Je voudrais un demi-pain de campagne, tranché, s'il vous plaît."},{"prompt":"Forma correcta: « Une baguette ______ (croustillant). »","answer":"croustillante"},{"prompt":"Escribe precio singular y plural para brioche.","answer":"Combien coûte la brioche ? / Combien coûtent les brioches ?"},{"prompt":"Corrige: « Je voudrais un pain frais et croustillant. C'est tout, je vais rester ici. »","answer":"Je voudrais un pain frais et croustillant. C'est tout, je vais emporter."},{"prompt":"Ordena: [ le ticket / Je peux avoir / Merci ! / Je vais emporter. / de caisse ? ]","answer":"Je vais emporter. Merci ! Je peux avoir le ticket de caisse ?"}]},"defiSteps":[{"serveur":"Bonjour ! Quelle belle matinée ! Le pain sort du four à l'instant — vous avez de la chance !","hint":"Saluda a Sophie y comenta el aroma del pan recién horneado.","example":"Bonjour Sophie ! Ça sent très bon ici — le pain est encore chaud !"},{"serveur":"Alors, qu'est-ce que je vous sers aujourd'hui ?","hint":"Pide una baguette especificando cocción (bien cuite) y forma (entière/demi/tranché).","example":"Je voudrais une baguette entière, bien cuite, s'il vous plaît."},{"serveur":"Parfait ! Et avec ça ?","hint":"Pregunta por el pain de campagne — su textura (croustillant/moelleux) y frescura.","example":"Vous avez du pain de campagne frais ? C'est croustillant ou moelleux ?"},{"serveur":"Oui, tout frais ! La croûte est croustillante, la mie est moelleuse.","hint":"Pregunta el precio con « Combien coûte… ».","example":"Combien coûte le pain de campagne ?"},{"serveur":"Deux euros cinquante le pain entier.","hint":"Decide la cantidad y la forma (entier / demi / tranché).","example":"Je prends un demi-pain, tranché, s'il vous plaît."},{"serveur":"Très bien ! Regardez ces brioches — elles sont sorties du four il y a 10 minutes.","hint":"Descubre las brioches, pregunta el precio y compra una.","example":"Combien coûtent les brioches ? J'en prends une, s'il vous plaît."},{"serveur":"Autre chose avec ça ?","hint":"Cierra la compra: « C'est tout » + « emporter ».","example":"Non, c'est tout, merci. Je vais emporter."},{"serveur":"Ça fait 4 euros 20, s'il vous plaît.","hint":"Paga, pide el ticket de caisse y despídete.","example":"Voilà. Je peux avoir le ticket de caisse, s'il vous plaît ? Merci, bonne journée !"}],"defiCriteria":["Saluda y usa fórmulas de cortesía apropiadas al contexto.","Emplea el vocabulario clave del día (La Boulangerie).","Aplica la estructura gramatical del día correctamente.","Responde a las preguntas del interlocutor sin cambiar al español.","Pide aclaración o repetición si no entiende algo.","Cierra la interacción con una despedida adecuada."],"tutor":{"role":"serveuse en un restaurante; el alumno viene a cenar","opener_fr":"Bonsoir ! Vous avez choisi ? Qu'est-ce que je vous sers ?","opener_es":"¡Buenas noches! ¿Ya eligió? ¿Qué le sirvo?","objectives":["Pide un plato principal y una bebida","Pide la cuenta (« L'addition, s'il vous plaît »)","Pregunta si puedes pagar con tarjeta"],"topic":"Au restaurant — pedir y pagar"},"meta":{"label":"Jour 3 · La Boulangerie","headTitle":"Jour 3 · La Boulangerie — Liberté","headDesc":"Jour 3 · La Boulangerie: lección completa del programa Liberté.","week":1,"weekEmoji":"🗼","intro":"Bienvenue au Jour 3 ! La Boulangerie Liberté. Respire, tu es prêt.","introSub":"La Boulangerie Liberté.","clesSub":"Quantités et politesse à la boulangerie.","defiTitle":"La Boulangerie","defiSubtitle":"Compra pan y viennoiserie como un parisino.","defiAvatar":"🗼"}}$rich$::jsonb)
