INSERT INTO public.authored_days (day_id, title, subtitle, status, rich) VALUES (4, 'Jour 4 · La Vitrine des Douceurs', 'Choisir, comparer et commander.', 'draft', $rich${"gym":"","vocabulary":[{"fr":"une tarte aux pommes","es":"una tarta de manzana","example":"Ça a l'air délicieux, cette tarte aux pommes !","emoji":"🥧"},{"fr":"une tarte au citron","es":"una tarta de limón","example":"Il reste une part de tarte au citron ?","emoji":"🍋"},{"fr":"un éclair","es":"un éclair","example":"Il reste des éclairs au chocolat ?","emoji":"🍫"},{"fr":"un macaron","es":"un macaron","example":"Je voudrais six macarons au citron, s'il vous plaît.","emoji":"🌈"},{"fr":"un chausson aux pommes","es":"una empanadilla de manzana","example":"Le chausson aux pommes, c'est fait maison ?","emoji":"🥟"},{"fr":"un cookie","es":"una galleta","example":"Je prends un cookie au chocolat, s'il vous plaît.","emoji":"🍪"},{"fr":"un mille-feuille","es":"un milhojas","example":"Le mille-feuille, c'est notre spécialité du samedi.","emoji":"🍰"},{"fr":"un financier","es":"un financier (pastelito de almendra)","example":"Les financiers sont moelleux et délicieux.","emoji":"🍯"},{"fr":"de la confiture","es":"mermelada","example":"Je voudrais du pain avec de la confiture, s'il vous plaît.","emoji":"🍓"},{"fr":"du miel","es":"miel","example":"Et avec du miel ? Vous en avez ?","emoji":"🍯"},{"fr":"du beurre","es":"mantequilla","example":"Une tartine de pain avec du beurre — c'est parfait !","emoji":"🧈"},{"fr":"fourré","es":"relleno","example":"C'est fourré à la crème ? Je vais essayer ça !","emoji":"🥮"},{"fr":"enrobé","es":"bañado / cubierto","example":"L'éclair est enrobé de chocolat noir.","emoji":"🍫"},{"fr":"la vitrine","es":"el escaparate / la vitrina","example":"Regardez ce qu'il y a dans la vitrine !","emoji":"🪟"},{"fr":"une boîte","es":"una caja","example":"Vous pouvez les mettre dans une boîte ?","emoji":"📦"},{"fr":"un cadeau","es":"un regalo","example":"C'est un cadeau — vous pouvez emballer ?","emoji":"🎁"},{"fr":"le présentoir","es":"el expositor","example":"Sophie arrange les macarons sur le présentoir.","emoji":"🍽️"},{"fr":"offrir","es":"regalar / ofrecer","example":"C'est pour offrir — je voudrais une belle présentation.","emoji":"💝"},{"fr":"goûter","es":"probar / saborear","example":"Je peux goûter avant de décider ?","emoji":"👅"},{"fr":"déguster","es":"degustar","example":"Prenez le temps de déguster — c'est fait maison.","emoji":"😋"},{"fr":"Qu'est-ce que vous recommandez ?","es":"¿Qué recomienda usted?","example":"Qu'est-ce que vous recommandez comme tarte ?","emoji":"❓"},{"fr":"Quelle est la spécialité ?","es":"¿Cuál es la especialidad?","example":"Quelle est la spécialité de la maison ?","emoji":"⭐"},{"fr":"C'est fait maison ?","es":"¿Es casero?","example":"L'éclair au chocolat, c'est fait maison ?","emoji":"🏠"},{"fr":"Il reste…","es":"Queda(n)…","example":"Il reste des macarons au citron ?","emoji":"🔎"},{"fr":"Je vais essayer ça.","es":"Voy a probar eso.","example":"Ça a l'air délicieux — je vais essayer ça !","emoji":"✅"},{"fr":"Ça a l'air délicieux.","es":"Parece delicioso.","example":"Ça a l'air délicieux ! C'est quoi, ce gâteau ?","emoji":"😍"},{"fr":"Ça sent bon !","es":"¡Huele bien!","example":"Ça sent tellement bon ici !","emoji":"👃"},{"fr":"populaire","es":"popular","example":"L'éclair est très populaire — il part vite !","emoji":"🔥"},{"fr":"disponible","es":"disponible","example":"La tarte au citron est disponible aujourd'hui seulement.","emoji":"🟢"},{"fr":"terminé","es":"agotado / acabado","example":"C'est terminé ? Dommage ! Je reviendrai demain.","emoji":"🚫"}],"flashQuiz":[{"emoji":"🥧","concept":"tarta de manzana","options":["une tarte aux pommes","un chausson aux pommes","un mille-feuille"],"answer":0},{"emoji":"🍋","concept":"tarta de limón","options":["une tarte au citron","un macaron","un financier"],"answer":0},{"emoji":"🍫","concept":"éclair de chocolate","options":["un éclair","un cookie","un mille-feuille"],"answer":0},{"emoji":"🌈","concept":"macaron colorido","options":["un macaron","un financier","un cookie"],"answer":0},{"emoji":"🥟","concept":"empanadilla de manzana","options":["un chausson aux pommes","une tarte aux pommes","un éclair"],"answer":0},{"emoji":"🍪","concept":"galleta","options":["un cookie","un financier","un macaron"],"answer":0},{"emoji":"🍰","concept":"milhojas","options":["un mille-feuille","un financier","un éclair"],"answer":0},{"emoji":"🍓","concept":"mermelada","options":["de la confiture","du miel","du beurre"],"answer":0},{"emoji":"🍯","concept":"miel","options":["du miel","de la confiture","du beurre"],"answer":0},{"emoji":"🧈","concept":"mantequilla","options":["du beurre","du miel","de la confiture"],"answer":0},{"emoji":"🪟","concept":"escaparate / vitrina","options":["la vitrine","le présentoir","une boîte"],"answer":0},{"emoji":"📦","concept":"caja de regalo","options":["une boîte","un cadeau","le présentoir"],"answer":0},{"emoji":"🎁","concept":"regalo","options":["un cadeau","une boîte","offrir"],"answer":0},{"emoji":"👅","concept":"probar antes de comprar","options":["goûter","déguster","offrir"],"answer":0},{"emoji":"🚫","concept":"agotado / se acabó","options":["terminé","disponible","populaire"],"answer":0}],"grammar":[{"formula":"ÇA A L'AIR + adjectif","use":"Para decir « parece / tiene pinta de ». El adjetivo va SIEMPRE en masculino singular."},{"formula":"IL RESTE + artículo + nombre / C'EST TERMINÉ","use":"Preguntar qué queda (Il reste des éclairs ?) o confirmar que se agotó (C'est terminé)."},{"formula":"C'EST POUR OFFRIR + boîte / cadeau","use":"Comprar un regalo y pedir presentación especial (boîte, ruban)."},{"formula":"VOUS POUVEZ ME LE FAIRE GOÛTER ?","use":"Pedir probar un producto de forma educada antes de decidir."}],"vocabGames":{"reading":[{"title":"Texte · Ana devant la vitrine","text":"Ana entre dans la boulangerie et regarde la vitrine. Elle voit des macarons colorés, des éclairs au chocolat et une belle tarte au citron. Elle dit : « Ça sent tellement bon ! Ça a l'air délicieux ! » Elle demande à Sophie : « Qu'est-ce que vous recommandez ? » Sophie répond : « Les éclairs sont très populaires — mais il en reste seulement deux. » Ana dit : « Vous pouvez me le faire goûter ? » Sophie lui donne un petit morceau. Ana sourit : « C'est incroyable ! Je vais essayer ça. Et c'est pour offrir — vous pouvez les mettre dans une boîte ? » Sophie répond : « Bien sûr, c'est un cadeau ! »","questions":[{"q":"¿Qué dice Ana cuando entra y huele el pan?","options":["Il reste des éclairs ?","Ça sent tellement bon ! Ça a l'air délicieux !","C'est terminé ? Dommage !"],"answer":1},{"q":"¿Por qué Sophie dice « il en reste seulement deux » ?","options":["Porque los éclairs ya están agotados.","Porque solo quedan dos éclairs disponibles.","Porque los éclairs son los menos populares."],"answer":1},{"q":"¿Para qué quiere Ana la boîte?","options":["Para llevar el pan sin que se aplaste.","Para guardar los macarons en la nevera.","Porque es para regalar — quiere una presentación especial."],"answer":2}]}],"listening":[{"audio":"Ça a l'air délicieux ! C'est quoi, ce gâteau ?","question":"¿Qué está expresando la cliente con estas dos frases?","options":["Que ya conoce ese pastel y lo quiere comprar.","Que el pastel parece delicioso y pregunta qué es.","Que el pastel huele bien pero no quiere probarlo."],"answer":1},{"audio":"Il reste des éclairs au chocolat ? C'est terminé ?","question":"¿Qué está verificando la cliente?","options":["Si los éclairs son caseros y cuánto cuestan.","Si todavía quedan éclairs o si ya se agotaron.","Si puede probar un éclair antes de comprar."],"answer":1},{"audio":"C'est pour offrir — vous pouvez le mettre dans une boîte ?","question":"¿Qué le pide la cliente a Sophie?","options":["Que le deje probar el producto antes de decidir.","Que el producto sea casero y fresco.","Que lo empaque en una caja porque es un regalo."],"answer":2},{"audio":"Vous pouvez me le faire goûter ?","question":"¿Qué solicitud educada está haciendo la cliente?","options":["Está pidiendo que le regalen el producto.","Está pidiendo permiso para probar el producto antes de comprarlo.","Está pidiendo el precio del producto."],"answer":1},{"audio":"La tarte au citron est disponible aujourd'hui seulement.","question":"¿Qué le está informando Sophie?","options":["Que la tarta de limón siempre está disponible.","Que la tarta de limón ya está agotada.","Que la tarta de limón solo está disponible hoy — es una oportunidad especial."],"answer":2}],"speaking":[{"situation":"Entras a la boulangerie y el olor te impacta. Reacciona con las dos frases del día.","expected":"Ça sent tellement bon ! Ça a l'air délicieux !"},{"situation":"Ves unos macarons pero no estás segura si quedan. Pregúntale a Sophie usando « Il reste ».","expected":"Il reste des macarons au citron ?"},{"situation":"Sophie dice que el éclair au chocolat es muy popular. Pide probarlo antes de decidir.","expected":"Vous pouvez me le faire goûter ?"},{"situation":"Compras seis macarons pero son un regalo. Pide una boîte.","expected":"C'est pour offrir — vous pouvez les mettre dans une boîte ?"},{"situation":"Sophie te dice que la tarte au citron se agotó. Reacciona.","expected":"C'est terminé ? Dommage !"}],"writing":[{"prompt":"Completa: « ______ tellement bon ici ! ______ l'air délicieux ! »","answer":"Ça sent / Ça a"},{"prompt":"Traduce: '¿Quedan éclairs de café?'","answer":"Il reste des éclairs au café ?"},{"prompt":"Transforma en regalo: « Je voudrais six macarons. » Añade que es para regalar y quieres una caja.","answer":"Je voudrais six macarons — c'est pour offrir. Vous pouvez les mettre dans une boîte ?"},{"prompt":"Corrige: « C'est finit ? Dommage ! » (adjetivo correcto para « agotado » en la boulangerie).","answer":"C'est terminé ? Dommage !"},{"prompt":"Ordena: [ goûter / me le / Vous pouvez / ? / faire ]","answer":"Vous pouvez me le faire goûter ?"}]},"clesReading":{"title":"Lecture · Isabelle devant la vitrine","text":"Isabelle entre dans la boulangerie. Elle regarde la vitrine et dit : « Oh ! Ça a l'air vraiment délicieux, ce mille-feuille ! » Sophie sourit : « Merci ! Il est très populaire. » Isabelle demande : « Il reste des éclairs au café ? » Sophie vérifie : « Non, désolée — c'est terminé pour les éclairs au café. Mais il reste des éclairs au chocolat ! » Isabelle dit : « Ça a l'air bon aussi. Vous pouvez me le faire goûter ? » Sophie lui donne un morceau. Isabelle : « C'est incroyable ! J'en prends deux. Et j'ai aussi besoin d'un cadeau pour mon amie — c'est pour offrir. Vous pouvez mettre les éclairs dans une boîte ? » Sophie : « Bien sûr ! Un joli cadeau parisien ! »","questions":[{"q":"Isabelle dice « Ça a l'air vraiment délicieux, ce mille-feuille ! ». ¿Por qué « délicieux » (masculino) ?","options":["Con « ça a l'air » el adjetivo siempre va en masculino singular, sea cual sea el objeto.","« Mille-feuille » siempre es masculino, por eso « délicieux ».","Es un error — debería ser « délicieuse »."],"answer":0},{"q":"Sophie dice « C'est terminé pour les éclairs au café ». ¿Qué significa?","options":["Que los éclairs de café no son populares.","Que los éclairs de café ya se agotaron.","Que los éclairs de café están disponibles solo los lunes."],"answer":1},{"q":"¿Qué logra Isabelle al decir « C'est pour offrir » ?","options":["Consigue un descuento por comprar varios éclairs.","Le indica a Sophie que quiere probar antes de comprar.","Le indica a Sophie que es un regalo y quiere presentación especial."],"answer":2}]},"clesGames":{"listening":[{"audio":"Ça a l'air délicieux, cette tarte ! Et ça a l'air frais aussi.","question":"El adjetivo es « délicieux » aunque « tarte » sea femenino. ¿Por qué?","options":["Con « ça a l'air », el adjetivo es siempre masculino singular — regla fija.","« Tarte » es masculino en francés.","Es un error — debería ser « délicieuse »."],"answer":0},{"audio":"Il reste des macarons au chocolat ? — Non, c'est terminé !","question":"¿Qué estructuras usan cliente y boulangère?","options":["« Je voudrais » para pedir y « non merci » para rechazar.","« Il reste » para preguntar si queda; « c'est terminé » para confirmar que se agotó.","« Combien coûte » para precio y « disponible » para confirmar."],"answer":1},{"audio":"C'est pour offrir — vous pouvez le mettre dans une boîte avec un ruban ?","question":"¿Qué dos elementos de presentación pide?","options":["Une boîte y un ruban.","Un cadeau y du papier.","Une vitrine y un présentoir."],"answer":0},{"audio":"Vous pouvez me le faire goûter ? Je vais essayer ça !","question":"¿Cuál es la diferencia entre las dos expresiones?","options":["Son sinónimas — significan lo mismo.","« Vous pouvez me le faire goûter » = petición educada para probar; « Je vais essayer ça » = decisión de comprar después de probar.","« Je vais essayer ça » es para preguntar el precio."],"answer":1},{"audio":"Il reste combien de macarons au citron ?","question":"¿Qué variante de « Il reste » usa el cliente?","options":["Pregunta sí/no si quedan macarons de limón.","Pregunta cuántos macarons de limón quedan — « combien » + il reste.","Dice que ya no quedan macarons de limón."],"answer":1}],"speaking":[{"situation":"Ves un mille-feuille increíble en la vitrina. Exprésalo con ÇA A L'AIR + adjectif.","expected":"Ça a l'air délicieux, ce mille-feuille !"},{"situation":"Pregunta si aún quedan tartas de manzana usando IL RESTE.","expected":"Il reste des tartes aux pommes ?"},{"situation":"Sophie te dice que los chaussons aux pommes se agotaron. Reacciona.","expected":"C'est terminé ? Dommage !"},{"situation":"Antes de comprar el éclair, pide probarlo de forma educada.","expected":"Vous pouvez me le faire goûter ?"},{"situation":"Compras seis macarons para regalar — pide caja y cinta.","expected":"C'est pour offrir — vous pouvez les mettre dans une boîte avec un ruban ?"}],"writing":[{"prompt":"Mira una tarte au citron. Escribe una frase con ÇA A L'AIR + dos adjetivos.","answer":"Ça a l'air délicieux et frais, cette tarte au citron !"},{"prompt":"Escribe dos versiones con IL RESTE: (a) ¿Quedan éclairs de chocolate? (b) ¿Cuántos macarons quedan?","answer":"(a) Il reste des éclairs au chocolat ? / (b) Il reste combien de macarons ?"},{"prompt":"Construye: 6 macarons como regalo + boîte + ruban.","answer":"C'est pour offrir — je voudrais six macarons dans une boîte avec un ruban."},{"prompt":"Corrige: « Je veux tester le macaron avant d'acheter. » (Usa la estructura más educada del día.)","answer":"Vous pouvez me le faire goûter ?"},{"prompt":"Ordena: [ Il reste / ? / des chaussons / — Non, / c'est terminé. / Dommage ! ]","answer":"Il reste des chaussons ? — Non, c'est terminé. Dommage !"}]},"defiSteps":[{"serveur":"Bonjour ! Vous tombez bien — les macarons viennent juste de sortir du four !","hint":"Saluda a Sophie y reacciona al aroma y a la vitrina.","example":"Bonjour Sophie ! Ça sent tellement bon ici — ça a l'air délicieux !"},{"serveur":"Regardez cette vitrine ! Qu'est-ce qui vous attire ?","hint":"Describe DOS productos que ves usando ÇA A L'AIR + adjectif.","example":"Ça a l'air délicieux, ce mille-feuille ! Et cette tarte au citron a l'air fraîche !"},{"serveur":"Tout est fait maison ce matin. Vous cherchez quelque chose de particulier ?","hint":"Pide una recomendación con QU'EST-CE QUE VOUS RECOMMANDEZ.","example":"Qu'est-ce que vous recommandez comme spécialité ?"},{"serveur":"Aujourd'hui, je vous recommande les éclairs au chocolat — notre spécialité !","hint":"Verifica si todavía quedan usando IL RESTE.","example":"Il reste des éclairs au chocolat ?"},{"serveur":"Oui, il en reste trois ! Ils sont très populaires.","hint":"Pide probar antes de decidir con VOUS POUVEZ ME LE FAIRE GOÛTER.","example":"Vous pouvez me le faire goûter avant de décider ?"},{"serveur":"Bien sûr, tenez ! Un petit morceau pour vous.","hint":"Después de probar, decide comprar con JE VAIS ESSAYER ÇA.","example":"C'est incroyable ! Je vais essayer ça — j'en prends trois."},{"serveur":"Parfait ! Trois éclairs au chocolat. Autre chose ?","hint":"Indica que es para regalar y pide une boîte con un ruban — C'EST POUR OFFRIR.","example":"C'est pour offrir — vous pouvez les mettre dans une boîte avec un ruban ?"},{"serveur":"Avec plaisir ! Un joli cadeau parisien. Ça fait 9 euros, s'il vous plaît.","hint":"Paga, agradece y despídete.","example":"Voilà. Merci beaucoup, Sophie. Bonne journée !"}],"defiCriteria":["Saluda y usa fórmulas de cortesía apropiadas al contexto.","Emplea el vocabulario clave del día (La Vitrine des Douceurs).","Aplica la estructura gramatical del día correctamente.","Responde a las preguntas del interlocutor sin cambiar al español.","Pide aclaración o repetición si no entiende algo.","Cierra la interacción con una despedida adecuada."],"tutor":{"role":"amiga francesa de visita en un mercado; charlan sobre comida","opener_fr":"Regarde tout ça ! Qu'est-ce que tu aimes manger, toi ?","opener_es":"¡Mira todo esto! ¿A ti qué te gusta comer?","objectives":["Di qué te gusta comer (« J'aime… »)","Describe un alimento (« C'est… »)","Pregúntale a Lib qué le gusta a ella"],"topic":"La nourriture — hablar de comida"},"meta":{"label":"Jour 4 · La Vitrine des Douceurs","headTitle":"Jour 4 · La Vitrine des Douceurs — Liberté","headDesc":"Jour 4 · La Vitrine des Douceurs: lección completa del programa Liberté.","week":1,"weekEmoji":"🗼","intro":"Bienvenue au Jour 4 ! La vitrine des douceurs. Respire, tu es prêt.","introSub":"La vitrine des douceurs.","clesSub":"Choisir, comparer et commander.","defiTitle":"La Vitrine des Douceurs","defiSubtitle":"Elige y pide en la pastelería.","defiAvatar":"🗼"}}$rich$::jsonb)
