INSERT INTO public.authored_days (day_id, title, subtitle, status, rich) VALUES (5, 'Jour 5 · Le Bistrot Liberté', 'Révision de la semaine 1.', 'draft', $rich${"gym":"","vocabulary":[{"fr":"le menu","es":"el menú (precio fijo)","example":"Je prends le menu, s'il vous plaît — entrée, plat et dessert.","emoji":"📋"},{"fr":"la carte","es":"la carta (à la carte)","example":"Vous pouvez m'apporter la carte, s'il vous plaît ?","emoji":"📖"},{"fr":"une entrée","es":"una entrada / primer plato","example":"Comme entrée, je prends la salade verte.","emoji":"🥗"},{"fr":"un plat principal","es":"un plato principal","example":"Comme plat principal, je voudrais le poulet.","emoji":"🍽️"},{"fr":"un dessert","es":"un postre","example":"Comme dessert, je vais prendre la tarte du jour.","emoji":"🍰"},{"fr":"une boisson","es":"una bebida","example":"Comme boisson, de l'eau plate, s'il vous plaît.","emoji":"🥤"},{"fr":"une soupe","es":"una sopa","example":"Comme entrée, je voudrais une soupe à l'oignon.","emoji":"🍲"},{"fr":"une salade","es":"una ensalada","example":"La salade niçoise, c'est la spécialité du bistrot.","emoji":"🥗"},{"fr":"du poisson","es":"pescado","example":"Je préfère le poisson à la viande — vous avez du poisson ?","emoji":"🐟"},{"fr":"de la viande","es":"carne","example":"Comme plat principal, je prends de la viande.","emoji":"🥩"},{"fr":"du poulet","es":"pollo","example":"Le poulet rôti avec des légumes — c'est parfait !","emoji":"🍗"},{"fr":"du riz","es":"arroz","example":"Avec du riz ou des pâtes ? Je préfère le riz.","emoji":"🍚"},{"fr":"des pâtes","es":"pasta","example":"Des pâtes à la bolognaise, s'il vous plaît.","emoji":"🍝"},{"fr":"des légumes","es":"verduras","example":"Je voudrais le poulet avec des légumes grillés.","emoji":"🥦"},{"fr":"une sauce","es":"una salsa","example":"Quelle sauce accompagne le poisson ?","emoji":"🥫"},{"fr":"du fromage","es":"queso","example":"Le fromage est compris dans le menu ?","emoji":"🧀"},{"fr":"du pain","es":"pan","example":"Vous pouvez m'apporter du pain, s'il vous plaît ?","emoji":"🥖"},{"fr":"une réservation","es":"una reserva","example":"J'ai une réservation au nom de García, pour deux personnes.","emoji":"📅"},{"fr":"une table pour deux","es":"una mesa para dos","example":"Je voudrais réserver une table pour deux ce soir.","emoji":"🍽️"},{"fr":"ce soir","es":"esta noche","example":"Vous avez une table disponible ce soir ?","emoji":"🌙"},{"fr":"à midi","es":"al mediodía","example":"Je voudrais réserver pour à midi, s'il vous plaît.","emoji":"☀️"},{"fr":"la terrasse","es":"la terraza","example":"Je préfère la terrasse à l'intérieur — il fait beau !","emoji":"🌿"},{"fr":"l'intérieur","es":"el interior","example":"Vous préférez la terrasse ou l'intérieur ce soir ?","emoji":"🏠"},{"fr":"disponible","es":"disponible","example":"Vous avez une table disponible pour ce soir ?","emoji":"🟢"},{"fr":"complet","es":"completo / sin mesa","example":"Désolé, nous sommes complets ce soir.","emoji":"🚫"},{"fr":"Je voudrais réserver.","es":"Quisiera reservar.","example":"Je voudrais réserver une table pour deux personnes, s'il vous plaît.","emoji":"📞"},{"fr":"À quelle heure ?","es":"¿A qué hora?","example":"À quelle heure voulez-vous dîner ?","emoji":"🕗"},{"fr":"Au nom de…","es":"A nombre de…","example":"J'ai réservé au nom de García.","emoji":"🪪"},{"fr":"annuler","es":"cancelar","example":"Je voudrais annuler ma réservation de ce soir.","emoji":"❌"},{"fr":"confirmer","es":"confirmar","example":"Je voudrais confirmer ma réservation pour demain soir.","emoji":"✅"}],"flashQuiz":[{"emoji":"📋","concept":"menú de precio fijo","options":["le menu","la carte","une entrée"],"answer":0},{"emoji":"📖","concept":"carta (à la carte)","options":["la carte","le menu","une réservation"],"answer":0},{"emoji":"🥗","concept":"entrada / primer plato","options":["une entrée","un plat principal","un dessert"],"answer":0},{"emoji":"🍽️","concept":"plato principal","options":["un plat principal","une entrée","une boisson"],"answer":0},{"emoji":"🍰","concept":"postre","options":["un dessert","une salade","du fromage"],"answer":0},{"emoji":"🐟","concept":"pescado","options":["du poisson","de la viande","du poulet"],"answer":0},{"emoji":"🥩","concept":"carne","options":["de la viande","du poulet","du poisson"],"answer":0},{"emoji":"🍗","concept":"pollo","options":["du poulet","de la viande","du poisson"],"answer":0},{"emoji":"🍚","concept":"arroz","options":["du riz","des pâtes","des légumes"],"answer":0},{"emoji":"🍝","concept":"pasta","options":["des pâtes","du riz","une salade"],"answer":0},{"emoji":"🥦","concept":"verduras","options":["des légumes","des pâtes","une sauce"],"answer":0},{"emoji":"🧀","concept":"queso","options":["du fromage","du pain","une sauce"],"answer":0},{"emoji":"🥖","concept":"pan","options":["du pain","du fromage","une boisson"],"answer":0},{"emoji":"📅","concept":"reserva","options":["une réservation","l'intérieur","la terrasse"],"answer":0},{"emoji":"🌿","concept":"terraza","options":["la terrasse","l'intérieur","complet"],"answer":0}],"grammar":[{"formula":"COMME + entrée / plat / dessert + je prends","use":"Pedir con elegancia los tres platos del menú, uno por uno."},{"formula":"JE PRÉFÈRE A À B","use":"Expresar preferencia entre dos opciones. Lo preferido primero, lo no preferido después de « à »."},{"formula":"AU NOM DE + apellido · disponible / complet / annuler / confirmer","use":"Gestionar una reserva: llegar, confirmar o cancelar."},{"formula":"Quel est le plat du jour ? · Qu'est-ce qui est compris ? · Vous pouvez m'apporter ?","use":"Las tres preguntas clave al serveur para brillar en el bistrot."}],"vocabGames":{"reading":[{"title":"Texte · Camille réserve au Bistrot Liberté","text":"Camille appelle le Bistrot Liberté. Elle demande : « Je voudrais réserver une table pour deux personnes ce soir. Vous êtes complets ? » Antoine répond : « Non, nous avons une table disponible à 20h. Au nom de qui ? » Camille dit : « Au nom de Dupont. » Le soir, elle arrive. Antoine lui demande : « Vous préférez la terrasse ou l'intérieur ? » Camille répond : « La terrasse, s'il vous plaît. » Antoine lui apporte le menu et la carte. Il dit : « Le menu à 25 euros comprend une entrée, un plat principal et un dessert. » Camille choisit le menu. Comme entrée, elle prend une soupe. Comme plat, du poulet avec des légumes. Elle demande aussi : « Le fromage est compris dans le menu ? » Antoine répond : « Oui, madame ! »","questions":[{"q":"¿Cómo verifica Camille si hay mesa disponible al llamar?","options":["Pregunta le plat du jour y la terrasse.","Dice 'Je voudrais réserver' y pregunta si están complets.","Pide confirmar su reserva anterior."],"answer":1},{"q":"¿Cuál es la diferencia entre le menu y la carte en este texto?","options":["Le menu es más caro que la carte.","Le menu es precio fijo (entrée + plat + dessert); la carte es a la carta.","No hay diferencia — son sinónimos en francés."],"answer":1},{"q":"¿Qué pide Camille como plato principal?","options":["Du poisson avec une sauce au citron.","Des pâtes avec du fromage.","Du poulet avec des légumes."],"answer":2}]}],"listening":[{"audio":"Je voudrais réserver une table pour deux personnes ce soir.","question":"¿Qué está haciendo la persona con esta frase?","options":["Está cancelando una reserva para esta noche.","Está reservando una mesa para dos personas esta noche.","Está preguntando si el restaurante está completo."],"answer":1},{"audio":"Désolé, nous sommes complets ce soir.","question":"¿Qué le está informando el restaurante al cliente?","options":["Que el menú está completo con todos los platos disponibles.","Que no hay mesas disponibles esta noche.","Que el cliente debe confirmar su reserva."],"answer":1},{"audio":"Comme entrée, je prends la soupe. Comme plat principal, le poulet.","question":"¿Qué estructura usa el cliente para hacer el pedido?","options":["Je voudrais + nombre del plato.","Comme + tipo de plato + je prends / nombre.","Il reste + tipo de plato."],"answer":1},{"audio":"Je préfère la terrasse à l'intérieur — il fait beau ce soir !","question":"¿Dónde prefiere sentarse el cliente, y por qué?","options":["En el interior, porque hace frío.","En la terraza, porque hace buen tiempo.","En la terraza, porque el interior está completo."],"answer":1},{"audio":"Le fromage est compris dans le menu ?","question":"¿Qué está preguntando el cliente al serveur?","options":["Si el queso es casero.","Si el queso está incluido en el precio fijo del menú.","Si hay queso en el plato principal."],"answer":1}],"speaking":[{"situation":"Llamas al Bistrot Liberté. Diles que quieres reservar una mesa para dos personas esta noche.","expected":"Je voudrais réserver une table pour deux personnes ce soir, s'il vous plaît."},{"situation":"El restaurante te pregunta a nombre de quién. Dales tu apellido usando la expresión correcta.","expected":"Au nom de García, s'il vous plaît."},{"situation":"Antoine te pregunta dónde prefieres sentarte. Dile que prefieres la terraza al interior.","expected":"Je préfère la terrasse à l'intérieur, s'il vous plaît."},{"situation":"Pide los tres platos de una sola vez usando COMME para cada uno: soupe / poisson / dessert.","expected":"Comme entrée, je prends la soupe. Comme plat principal, le poisson. Comme dessert, la tarte du jour."},{"situation":"Durante la comida, pide a Antoine que te traiga pan y agua.","expected":"Vous pouvez m'apporter du pain et de l'eau, s'il vous plaît ?"}],"writing":[{"prompt":"Completa la frase para hacer una reserva: « Je voudrais ____ une table pour ____ personnes ____ soir. »","answer":"réserver / deux / ce"},{"prompt":"¿Cómo le dices al restaurante a nombre de quién está la reserva? (Usa tu apellido o García.)","answer":"J'ai une réservation au nom de García."},{"prompt":"Escribe tu pedido completo de los tres platos usando COMME para cada uno.","answer":"Comme entrée, je prends la salade. Comme plat principal, je voudrais du poisson. Comme dessert, le fromage."},{"prompt":"Corrige: « Le menu est la liste de tous les plats du restaurant. » (Pista: definición correcta en francés.)","answer":"Non — le menu en France = prix fixe (entrée + plat + dessert). La liste de tous les plats s'appelle 'la carte'."},{"prompt":"Ordena: [ est compris / Le fromage / dans le menu / ? ]","answer":"Le fromage est compris dans le menu ?"}]},"clesReading":{"title":"Lecture · Lucas dîne au Bistrot Liberté","text":"Lucas arrive au Bistrot Liberté. Il dit à Antoine : « Bonsoir ! J'ai une réservation au nom de Martin, pour deux personnes. » Antoine vérifie et répond : « Très bien, monsieur Martin ! Vous préférez la terrasse ou l'intérieur ? » Lucas : « Je préfère la terrasse à l'intérieur — il fait très beau ce soir. » Antoine leur apporte le menu. Lucas demande : « Quel est le plat du jour ? » Antoine répond : « Un filet de poisson avec une sauce au citron. » Lucas commande : « Comme entrée, je prends la soupe. Comme plat principal, le poisson, s'il vous plaît. Je préfère le poisson à la viande. Comme dessert — qu'est-ce qui est compris dans le menu ? » Antoine : « Le fromage ou un dessert sucré. » Lucas : « Alors le fromage, merci. Et vous pouvez m'apporter du pain ? »","questions":[{"q":"Lucas usa JE PRÉFÈRE A À B dos veces. ¿Cuáles son?","options":["Je préfère la terrasse à l'intérieur + Je préfère le poisson à la viande.","Je préfère le menu à la carte + Je préfère le fromage au dessert.","Je préfère la soupe à la salade + Je préfère le pain au fromage."],"answer":0},{"q":"¿Qué estructura usa Lucas para el pedido completo de los tres platos?","options":["Je voudrais + nombre del plato (tres veces).","COMME + tipo de plato + je prends / nombre del plato.","Il reste + tipo de plato + je vais essayer."],"answer":1},{"q":"¿Qué pregunta usa Lucas para saber qué incluye el menú?","options":["Quel est le plat du jour ?","Vous pouvez m'apporter le fromage ?","Qu'est-ce qui est compris dans le menu ?"],"answer":2}]},"clesGames":{"listening":[{"audio":"Comme entrée, je prends la soupe. Comme plat principal, le poisson. Comme dessert, la tarte.","question":"¿Qué estructura usa el cliente para hacer el pedido completo?","options":["Je voudrais + nombre del plato (para cada uno).","COMME + tipo de plato + nombre del plato — para los tres cursos en orden.","Il reste + tipo de plato — para verificar disponibilidad."],"answer":1},{"audio":"Je préfère le poisson à la viande.","question":"¿Qué significa esta frase y cuál es el orden de la estructura?","options":["La persona prefiere la viande al poisson.","La persona prefiere el poisson — lo que prefiere va primero, lo que prefiere menos va después de 'à'.","La persona no tiene preferencia entre los dos."],"answer":1},{"audio":"J'ai une réservation au nom de Dupont, pour deux personnes.","question":"¿Qué dos datos esenciales da el cliente al llegar?","options":["El menú elegido y la hora de llegada.","El apellido de la reserva y el número de personas.","La preferencia de mesa y el tipo de boisson."],"answer":1},{"audio":"Quel est le plat du jour ? Et qu'est-ce qui est compris dans le menu ?","question":"¿Para qué se usan estas dos preguntas?","options":["Para preguntar el precio y pedir la cuenta.","Para saber qué se recomienda ese día y qué incluye el precio fijo.","Para cancelar la reserva y pedir otra mesa."],"answer":1},{"audio":"Vous pouvez m'apporter du pain et de l'eau plate, s'il vous plaît ?","question":"¿Qué estructura usa el cliente para pedir algo durante la comida?","options":["Comme + nombre del producto.","Il reste + artículo + nombre.","Vous pouvez m'apporter + artículo + nombre."],"answer":2}],"speaking":[{"situation":"Antoine te pregunta 'Vous prenez le menu ou la carte ?' Responde que tomas el menú y pide los tres platos usando COMME.","expected":"Je prends le menu. Comme entrée, la salade. Comme plat principal, le poulet. Comme dessert, la tarte."},{"situation":"Antoine te pregunta si prefieres la terraza o el interior. Usa JE PRÉFÈRE A À B.","expected":"Je préfère la terrasse à l'intérieur, s'il vous plaît."},{"situation":"Llegas con reserva. Di tu nombre y el número de personas usando AU NOM DE.","expected":"J'ai une réservation au nom de García, pour deux personnes."},{"situation":"Quieres saber qué es el plato del día. Formula la pregunta correcta al serveur.","expected":"Quel est le plat du jour ?"},{"situation":"Durante la comida necesitas pan y quieres saber qué incluye el menú. Haz las dos preguntas.","expected":"Vous pouvez m'apporter du pain ? Et qu'est-ce qui est compris dans le menu ?"}],"writing":[{"prompt":"Construye el pedido completo de una cena usando COMME para los tres cursos.","answer":"Comme entrée, je prends la soupe. Comme plat principal, du poisson avec des légumes. Comme dessert, le plateau de fromages."},{"prompt":"Expresa dos preferencias con JE PRÉFÈRE A À B: (a) poisson vs viande / (b) terrasse vs intérieur.","answer":"(a) Je préfère le poisson à la viande. / (b) Je préfère la terrasse à l'intérieur."},{"prompt":"Escribe la frase completa para presentarte con tu reserva al llegar: nombre García, 2 personas.","answer":"J'ai une réservation au nom de García, pour deux personnes."},{"prompt":"Corrige: « Je veux savoir le plat aujourd'hui. » (Usa la pregunta elegante del día.)","answer":"Quel est le plat du jour ?"},{"prompt":"Ordena: [ je voudrais / Comme plat principal / le poulet / avec des légumes / , ]","answer":"Comme plat principal, je voudrais le poulet avec des légumes."}]},"defiSteps":[{"serveur":"Bonsoir, madame ! Bienvenue au Bistrot Liberté. Vous avez une réservation ?","hint":"Preséntate con AU NOM DE + apellido y el número de personas.","example":"Bonsoir ! Oui, j'ai une réservation au nom de García, pour deux personnes."},{"serveur":"Parfait, madame García ! Vous préférez la terrasse ou l'intérieur ?","hint":"Usa JE PRÉFÈRE A À B para elegir la mesa.","example":"Je préfère la terrasse à l'intérieur, s'il vous plaît — il fait beau ce soir."},{"serveur":"Très bien ! Voici le menu et la carte. Vous avez besoin d'un moment ?","hint":"Pregunta cuál es el plat du jour.","example":"Merci ! Quel est le plat du jour ?"},{"serveur":"Un filet de poisson avec des légumes grillés et une sauce au citron.","hint":"Elige entre menu o carte y explica brevemente la diferencia.","example":"Je prends le menu — c'est le prix fixe avec entrée, plat et dessert, non ?"},{"serveur":"Exactement ! 28 euros. Qu'est-ce que vous prenez ?","hint":"Pide los tres platos usando COMME para cada uno.","example":"Comme entrée, la soupe. Comme plat principal, le poisson. Comme dessert, la tarte du jour."},{"serveur":"Excellent choix ! Le poisson ou la viande vous plaît davantage ?","hint":"Expresa una preferencia de ingrediente con JE PRÉFÈRE A À B.","example":"Je préfère le poisson à la viande — c'est plus léger."},{"serveur":"Je note tout ça. Vous voulez boire quelque chose en attendant ?","hint":"Pide pan y agua con VOUS POUVEZ M'APPORTER.","example":"Vous pouvez m'apporter du pain et de l'eau plate, s'il vous plaît ?"},{"serveur":"Bien sûr, je vous apporte ça tout de suite !","hint":"Pregunta qué incluye el menú con QU'EST-CE QUI EST COMPRIS.","example":"Qu'est-ce qui est compris dans le menu ? Le fromage aussi ?"},{"serveur":"Voilà votre plat — le poisson avec une sauce au citron.","hint":"Reacciona al plato con ÇA A L'AIR + adjectif.","example":"Ça a l'air délicieux ! Et ça sent tellement bon !"},{"serveur":"Je vous laisse déguster ! Vous voulez la carte des desserts ?","hint":"Pide la cuenta, paga y despídete de Antoine.","example":"L'addition, s'il vous plaît. Merci beaucoup, Antoine. Bonne soirée !"}],"defiCriteria":["Saluda y usa fórmulas de cortesía apropiadas al contexto.","Emplea el vocabulario clave del día (Le Bistrot Liberté).","Aplica la estructura gramatical del día correctamente.","Responde a las preguntas del interlocutor sin cambiar al español.","Pide aclaración o repetición si no entiende algo.","Cierra la interacción con una despedida adecuada."],"tutor":{"role":"serveuse en un café-restaurante; gran repaso de la semana","opener_fr":"Bonjour ! Installez-vous. Qu'est-ce que je vous sers aujourd'hui ?","opener_es":"¡Hola! Siéntese. ¿Qué le sirvo hoy?","objectives":["Pide una bebida y algo de comer con cortesía","Haz una pregunta al serveur (precio, recomendación…)","Paga y despídete como un parisino"],"topic":"Au café-restaurant — repaso de la semana 1"},"meta":{"label":"Jour 5 · Le Bistrot Liberté","headTitle":"Jour 5 · Le Bistrot Liberté — Liberté","headDesc":"Jour 5 · Le Bistrot Liberté: lección completa del programa Liberté.","week":1,"weekEmoji":"🗼","intro":"Bienvenue au Jour 5 ! Le bistrot Liberté. Respire, tu es prêt.","introSub":"Le bistrot Liberté.","clesSub":"Révision de la semaine 1.","defiTitle":"Le Bistrot Liberté","defiSubtitle":"Une commande complète au bistrot.","defiAvatar":"🗼"}}$rich$::jsonb)
