INSERT INTO public.authored_days (day_id, title, subtitle, status, rich) VALUES (6, 'Jour 6 · Restaurant · Partie 2', 'Régimes, allergies et addition.', 'draft', $rich${"gym":"https://www.youtube.com/embed/kLuB1ZDjkHg","vocabulary":[{"fr":"végétarien","es":"vegetariano","example":"Je suis végétarien, je ne mange pas de viande.","emoji":"🥗"},{"fr":"végane","es":"vegano","example":"Elle est végane — pas de produits animaux.","emoji":"🌱"},{"fr":"une allergie","es":"una alergia","example":"J'ai une allergie aux fruits de mer.","emoji":"🤧"},{"fr":"sans gluten","es":"sin gluten","example":"Vous avez un menu sans gluten ?","emoji":"🌾"},{"fr":"épicé","es":"picante","example":"C'est épicé ? Je ne supporte pas le piment.","emoji":"🌶️"},{"fr":"la cuisson","es":"el punto de cocción","example":"Quelle cuisson pour votre steak ?","emoji":"🍳"},{"fr":"à point","es":"en su punto","example":"Je voudrais mon steak à point.","emoji":"🥩"},{"fr":"saignant","es":"poco hecho","example":"Mon mari aime le steak saignant.","emoji":"🩸"},{"fr":"le total","es":"el total","example":"Le total, c'est combien ?","emoji":"💰"},{"fr":"service compris","es":"servicio incluido","example":"Le service est compris dans le prix.","emoji":"🤵"},{"fr":"arrondir","es":"redondear","example":"Je peux arrondir à 20 euros ?","emoji":"🔄"},{"fr":"partager","es":"compartir / dividir","example":"On peut partager l'addition ?","emoji":"🤝"},{"fr":"séparément","es":"por separado","example":"On paie séparément, s'il vous plaît.","emoji":"✂️"},{"fr":"une erreur","es":"un error","example":"Il y a une erreur dans l'addition.","emoji":"⚠️"},{"fr":"le plat du jour","es":"el plato del día","example":"Quel est le plat du jour ?","emoji":"🍽️"},{"fr":"le menu enfant","es":"el menú infantil","example":"Vous avez un menu enfant ?","emoji":"🧒"},{"fr":"Je vais prendre…","es":"Voy a tomar…","example":"Je vais prendre le poulet rôti.","emoji":"🍗"},{"fr":"Je prends…","es":"Tomo…","example":"Je prends la salade verte.","emoji":"🥬"},{"fr":"Qu'est-ce qu'il y a dans ce plat ?","es":"¿Qué lleva este plato?","example":"Qu'est-ce qu'il y a dans ce plat ?","emoji":"❓"},{"fr":"Vous avez quelque chose pour… ?","es":"¿Tiene algo para…?","example":"Vous avez quelque chose pour les végétariens ?","emoji":"🙋"},{"fr":"C'est délicieux !","es":"¡Está delicioso!","example":"C'est délicieux, compliments au chef !","emoji":"😋"},{"fr":"un accompagnement","es":"un acompañamiento","example":"Qu'est-ce qui vient en accompagnement ?","emoji":"🥔"},{"fr":"une portion","es":"una porción","example":"C'est une grande portion ?","emoji":"🍚"},{"fr":"par carte bancaire","es":"con tarjeta bancaria","example":"Je peux payer par carte bancaire ?","emoji":"💳"},{"fr":"faire moitié-moitié","es":"pagar a medias","example":"On fait moitié-moitié ?","emoji":"➗"},{"fr":"savourer","es":"saborear","example":"Prenez le temps de savourer ce plat.","emoji":"🥂"},{"fr":"doux","es":"suave / sin picante","example":"Je préfère quelque chose de doux.","emoji":"🍯"},{"fr":"copieux","es":"abundante","example":"Ce plat est très copieux.","emoji":"🍛"},{"fr":"un supplément","es":"un extra","example":"Il y a un supplément pour la sauce ?","emoji":"➕"},{"fr":"Compliments au chef !","es":"¡Mis felicitaciones al chef!","example":"Compliments au chef, c'était excellent !","emoji":"👨‍🍳"}],"flashQuiz":[{"emoji":"🥗","concept":"vegetariano","options":["végétarien","végane","sans gluten"],"answer":0},{"emoji":"🌱","concept":"vegano (sin productos animales)","options":["végétarien","végane","doux"],"answer":1},{"emoji":"🤧","concept":"alergia alimentaria","options":["une allergie","une erreur","une portion"],"answer":0},{"emoji":"🌾","concept":"sin gluten","options":["sans gluten","épicé","doux"],"answer":0},{"emoji":"🌶️","concept":"picante","options":["doux","épicé","copieux"],"answer":1},{"emoji":"🥩","concept":"en su punto (cocción)","options":["saignant","à point","épicé"],"answer":1},{"emoji":"🩸","concept":"poco hecho (rojo)","options":["à point","saignant","doux"],"answer":1},{"emoji":"⚠️","concept":"error en la cuenta","options":["une erreur","une portion","un supplément"],"answer":0},{"emoji":"✂️","concept":"pagar por separado","options":["séparément","arrondir","partager"],"answer":0},{"emoji":"➗","concept":"pagar a medias","options":["faire moitié-moitié","partager","arrondir"],"answer":0},{"emoji":"🍽️","concept":"plato del día","options":["le plat du jour","le menu enfant","un supplément"],"answer":0},{"emoji":"🥔","concept":"acompañamiento","options":["une portion","un accompagnement","un supplément"],"answer":1},{"emoji":"🍛","concept":"abundante","options":["copieux","doux","épicé"],"answer":0},{"emoji":"💳","concept":"pago con tarjeta bancaria","options":["par carte bancaire","arrondir","service compris"],"answer":0},{"emoji":"👨‍🍳","concept":"felicitar al chef","options":["Compliments au chef !","Bonne journée !","C'est délicieux !"],"answer":0}],"grammar":[{"formula":"ALLER (conjugado) + INFINITIF = FUTUR PROCHE","use":"Expresar una acción muy próxima o una decisión: « Je vais prendre le poulet »."},{"formula":"JE SUIS + adjectif alimentaire","use":"Anunciar una restricción: végétarien, végane, allergique, sans gluten."},{"formula":"IL Y A UNE ERREUR + DANS + article + nom","use":"Señalar un error educadamente: « Il y a une erreur dans l'addition »."},{"formula":"ON PEUT + INFINITIF","use":"Sugerir o pedir permiso: partager, payer séparément, faire moitié-moitié."}],"vocabGames":{"reading":[{"title":"Texte · Un dîner entre amis","text":"Léa et ses amis entrent dans un petit restaurant à Paris. Léa est végétarienne et son ami Paul a une allergie aux fruits de mer. Le serveur les accueille : « Bonsoir ! Voici la carte. » Léa demande : « Vous avez quelque chose pour les végétariens ? » Le serveur répond : « Oui, le plat du jour est un risotto aux légumes, et il est sans gluten aussi. » Paul demande : « Qu'est-ce qu'il y a dans ce plat ? » Le serveur explique. À la fin du dîner, Léa remarque une erreur dans l'addition : ils ont compté un dessert de trop. Le serveur corrige tout de suite. Ils décident de payer séparément par carte bancaire. Avant de partir, Léa dit : « C'était délicieux, compliments au chef ! »","questions":[{"q":"¿Qué restricción tiene Léa?","options":["Es vegana","Es vegetariana","Es alérgica al gluten"],"answer":1},{"q":"¿Qué error hay en la cuenta?","options":["Contaron un postre de más.","Contaron dos platos de más.","Cobraron el servicio dos veces."],"answer":0},{"q":"¿Cómo deciden pagar?","options":["En efectivo","A medias en efectivo","Por separado con tarjeta bancaria"],"answer":2}]}],"listening":[{"audio":"Je suis végétarien, je ne mange pas de viande.","question":"¿Qué está anunciando el cliente?","options":["Que es vegano","Que es vegetariano","Que tiene una alergia"],"answer":1},{"audio":"Il y a une erreur dans l'addition.","question":"¿Qué acaba de decir el cliente?","options":["Que quiere pagar la cuenta.","Que hay un error en la cuenta.","Que quiere dividir la cuenta."],"answer":1},{"audio":"On peut payer séparément, s'il vous plaît ?","question":"¿Qué está pidiendo?","options":["Pagar a medias.","Pagar en efectivo.","Pagar por separado."],"answer":2},{"audio":"Je voudrais mon steak à point.","question":"¿Qué cocción está pidiendo?","options":["Poco hecho","En su punto","Muy hecho"],"answer":1},{"audio":"Vous avez quelque chose pour les végétariens ?","question":"¿Qué está preguntando?","options":["Si el plato es picante.","Si tienen algo apto para vegetarianos.","Si hay menú infantil."],"answer":1}],"speaking":[{"situation":"Anuncia que eres vegetariano y pregunta si tienen algo para ti.","expected":"Je suis végétarien. Vous avez quelque chose pour les végétariens ?"},{"situation":"Descubres un error en la cuenta. Díselo al camarero con educación.","expected":"Excusez-moi, il y a une erreur dans l'addition."},{"situation":"Pide pagar por separado con tarjeta bancaria.","expected":"On peut payer séparément, par carte bancaire ?"},{"situation":"El camarero pregunta la cocción de tu steak. Pídelo en su punto.","expected":"Je voudrais mon steak à point, s'il vous plaît."},{"situation":"Al terminar, felicita al chef y despídete.","expected":"C'était délicieux, compliments au chef ! Bonne soirée !"}],"writing":[{"prompt":"Traduce: '¿Tienen un menú sin gluten?'","answer":"Vous avez un menu sans gluten ?"},{"prompt":"Completa: « Il y a une ______ dans l'addition. »","answer":"erreur"},{"prompt":"Traduce: 'Vamos a pagar por separado.'","answer":"On va payer séparément."},{"prompt":"Corrige: « Je veux mon steak saignant, à point. »","answer":"Je voudrais mon steak à point, s'il vous plaît."},{"prompt":"Ordena: [ pour / vous avez / les végétariens / quelque chose / ? ]","answer":"Vous avez quelque chose pour les végétariens ?"}]},"clesReading":{"title":"Lecture · Le futur proche au restaurant","text":"Antoine et Sophie sont au restaurant. Antoine regarde la carte et dit : « Je vais prendre le plat du jour — un risotto aux champignons. » Sophie répond : « Moi, je vais essayer le poulet rôti avec des légumes. » Le serveur arrive. Antoine ajoute : « Nous allons partager une bouteille d'eau plate. » À la fin du repas, Sophie remarque quelque chose : « Attends, il y a une erreur dans l'addition — ils ont compté un dessert de trop. » Antoine appelle le serveur : « Excusez-moi, on va vérifier l'addition ensemble ? » Le serveur corrige. Antoine sourit : « Merci ! On va payer séparément. » Sophie ajoute : « Je vais payer par carte bancaire. »","questions":[{"q":"¿Qué estructura usan Antoine y Sophie para anunciar sus decisiones inmediatas?","options":["Je voudrais + sustantivo.","Aller (conjugado) + infinitif — futur proche.","Je préfère + sustantivo."],"answer":1},{"q":"¿Cómo se dice « Vamos a pagar por separado » en futur proche?","options":["Nous payons séparément.","On va payer séparément.","On veut payer séparément."],"answer":1},{"q":"¿Cuál es el error frecuente que hay que evitar?","options":["Je vais prends le poulet (❌) → je vais prendre le poulet (✓).","Je vais prendre le poulet (❌) → je prends le poulet (✓).","Je vais prendre le poulet (❌) → j'ai pris le poulet (✓)."],"answer":0}]},"clesGames":{"listening":[{"audio":"Je vais prendre le plat du jour.","question":"¿Qué tiempo verbal se usa?","options":["Présent — acción actual.","Futur proche — decisión inmediata.","Passé composé — acción pasada."],"answer":1},{"audio":"On va payer séparément.","question":"¿Cuál es la traducción correcta?","options":["Pagamos por separado (habitual).","Vamos a pagar por separado.","Pagamos a medias."],"answer":1},{"audio":"Elle va demander l'addition.","question":"¿Qué expresa esta frase?","options":["Ella pidió la cuenta hace un rato.","Ella va a pedir la cuenta (dentro de un momento).","Ella siempre pide la cuenta."],"answer":1},{"audio":"Nous allons réserver une table pour samedi.","question":"¿Qué estructura reconoces?","options":["Devoir + infinitif.","Aller + infinitif (futur proche).","Vouloir + infinitif."],"answer":1},{"audio":"Je vais prends le poulet rôti.","question":"Esta frase tiene un error. ¿Cuál?","options":["Debería decir « Je prends prends ».","Debería decir « Je vais prendre le poulet rôti » — aller siempre va con el infinitif.","Está correcta."],"answer":1}],"speaking":[{"situation":"Anuncia con futur proche que vas a tomar el plato del día.","expected":"Je vais prendre le plat du jour, s'il vous plaît."},{"situation":"Di con futur proche que van a pagar por separado.","expected":"On va payer séparément."},{"situation":"Anuncia con futur proche que vas a reservar una mesa para el sábado.","expected":"Je vais réserver une table pour samedi."},{"situation":"Di con futur proche que vas a probar el postre casero.","expected":"Je vais essayer le dessert fait maison."},{"situation":"Anuncia con futur proche que van a compartir la cuenta.","expected":"On va partager l'addition."}],"writing":[{"prompt":"Completa con futur proche: « Je ______ prendre le steak à point. »","answer":"vais"},{"prompt":"Corrige el futur proche: « Elle va demande l'addition. »","answer":"Elle va demander l'addition."},{"prompt":"Traduce: 'Vamos a pagar por separado.'","answer":"On va payer séparément."},{"prompt":"Ordena: [ vais / je / commander / un / steak ]","answer":"Je vais commander un steak."},{"prompt":"Reescribe en futur proche: « Nous réservons une table pour deux. »","answer":"Nous allons réserver une table pour deux."}]},"defiSteps":[{"serveur":"Bonjour ! Bienvenue. Vous avez une réservation ?","hint":"Explica que reservaste para el sábado a las 20h para 2 personas — usa futur proche si puedes.","example":"Bonjour ! Oui, j'ai réservé pour samedi à 20h — nous allons être deux."},{"serveur":"Parfait. Voici la carte. Vous avez choisi ?","hint":"Anuncia una restricción alimentaria (végétarien / végane / sans gluten / allergie) y pide una recomendación.","example":"Je suis végétarien. Vous avez quelque chose pour les végétariens ?"},{"serveur":"Bien sûr, je vais vous recommander notre plat du jour.","hint":"Usa « Je vais prendre… » (futur proche) para pedir tu plato y precisar cuisson o accompagnement.","example":"Très bien, je vais prendre le plat du jour, avec des légumes en accompagnement."},{"serveur":"Voilà l'addition. Ça fait 48 euros.","hint":"Descubre un error en la cuenta y coméntalo con educación.","example":"Excusez-moi, je crois qu'il y a une erreur dans l'addition — vous avez compté deux desserts."},{"serveur":"Ah, vous avez raison, je corrige tout de suite. Comment vous payez ?","hint":"Pide pagar por separado o a medias, y despídete felicitando al chef.","example":"On va payer séparément, par carte bancaire. Compliments au chef, c'était délicieux !"}],"defiCriteria":["Saluda y usa fórmulas de cortesía apropiadas al contexto.","Emplea el vocabulario clave del día (Restaurant · Partie 2).","Aplica la estructura gramatical del día correctamente.","Responde a las preguntas del interlocutor sin cambiar al español.","Pide aclaración o repetición si no entiende algo.","Cierra la interacción con una despedida adecuada."],"tutor":{"role":"serveuse en un restaurante elegante; la experiencia completa","opener_fr":"Bonsoir ! Vous avez une réservation ?","opener_es":"¡Buenas noches! ¿Tiene una reserva?","objectives":["Pide una mesa para dos","Pide un menú completo (entrada, plato, bebida)","Reacciona a la comida (« C'est délicieux ! »)"],"topic":"À table — el restaurante completo"},"meta":{"label":"Jour 6 · Restaurant · Partie 2","headTitle":"Jour 6 · Restaurant · Partie 2 — Liberté","headDesc":"Jour 6 · Restaurant · Partie 2: lección completa del programa Liberté.","week":2,"weekEmoji":"🍽️","intro":"Bienvenue au Jour 6 ! Le restaurant, partie 2. Respire, tu es prêt.","introSub":"Le restaurant, partie 2.","clesSub":"Régimes, allergies et addition.","defiTitle":"Restaurant · Partie 2","defiSubtitle":"Cena completa: pide, adapta el plato y paga.","defiAvatar":"🍽️"}}$rich$::jsonb)
ON CONFLICT (day_id) DO NOTHING;
INSERT INTO public.authored_days (day_id, title, subtitle, status, rich) VALUES (7, 'Jour 7 · Supermarché · Partie 1', 'Trouver les rayons et demander de l''aide.', 'draft', $rich${"gym":"https://www.youtube.com/embed/AdJPOTR-CdU","vocabulary":[{"fr":"un supermarché","es":"un supermercado","example":"Je vais au supermarché ce matin.","emoji":"🏬"},{"fr":"un rayon","es":"una sección / pasillo","example":"Le rayon fromages est au fond.","emoji":"🧀"},{"fr":"une caisse","es":"una caja","example":"Il y a une longue file à la caisse.","emoji":"💵"},{"fr":"un chariot","es":"un carrito","example":"Je prends un chariot — j'ai beaucoup à acheter.","emoji":"🛒"},{"fr":"un panier","es":"una cesta","example":"Je prends juste un panier — c'est rapide.","emoji":"🧺"},{"fr":"un sac","es":"una bolsa","example":"Vous voulez un sac ?","emoji":"🛍️"},{"fr":"une liste de courses","es":"una lista de compras","example":"J'ai oublié ma liste de courses !","emoji":"📝"},{"fr":"une marque","es":"una marca","example":"Je préfère les marques françaises.","emoji":"🏷️"},{"fr":"cher / pas cher","es":"caro / barato","example":"Ce produit est trop cher.","emoji":"💶"},{"fr":"une promotion","es":"una oferta","example":"Il y a des promotions cette semaine.","emoji":"🎉"},{"fr":"une réduction","es":"un descuento","example":"Il y a une réduction de 30 %.","emoji":"📉"},{"fr":"une étiquette","es":"una etiqueta","example":"Lisez bien l'étiquette avant d'acheter.","emoji":"🏷️"},{"fr":"la date de péremption","es":"la fecha de caducidad","example":"La date de péremption, c'est demain.","emoji":"📅"},{"fr":"frais","es":"fresco","example":"Le pain frais est livré chaque matin.","emoji":"🥖"},{"fr":"surgelé","es":"congelado","example":"Je cherche les produits surgelés.","emoji":"🧊"},{"fr":"une conserve","es":"una conserva","example":"J'achète des conserves pour la semaine.","emoji":"🥫"},{"fr":"bio","es":"ecológico / orgánico","example":"Je préfère les légumes bio.","emoji":"🌿"},{"fr":"une allée","es":"un pasillo","example":"Les céréales sont dans l'allée 3.","emoji":"🛤️"},{"fr":"l'entrée","es":"la entrada","example":"Le parking est près de l'entrée.","emoji":"🚪"},{"fr":"la sortie","es":"la salida","example":"La sortie est à droite.","emoji":"🚶"},{"fr":"Où se trouve… ?","es":"¿Dónde está…?","example":"Où se trouve le rayon boulangerie ?","emoji":"❓"},{"fr":"Je cherche…","es":"Busco…","example":"Je cherche le rayon fromages.","emoji":"🔎"},{"fr":"au fond","es":"al fondo","example":"Les surgelés sont au fond du magasin.","emoji":"⬇️"},{"fr":"à gauche / à droite","es":"a la izquierda / a la derecha","example":"C'est à gauche, après les caisses.","emoji":"↔️"},{"fr":"Il y a…","es":"Hay…","example":"Il y a du pain frais aujourd'hui ?","emoji":"✅"},{"fr":"Il n'y a pas de…","es":"No hay…","example":"Il n'y a pas de lait demi-écrémé.","emoji":"🚫"},{"fr":"les soldes","es":"las rebajas","example":"Les soldes commencent ce weekend.","emoji":"🔖"},{"fr":"la qualité","es":"la calidad","example":"Ce produit est de bonne qualité.","emoji":"⭐"},{"fr":"une offre","es":"una oferta especial","example":"Il y a une offre spéciale sur le fromage.","emoji":"🎁"},{"fr":"un produit","es":"un producto","example":"Ce produit est excellent rapport qualité-prix.","emoji":"📦"}],"flashQuiz":[{"emoji":"🏬","concept":"supermercado","options":["un supermarché","un rayon","une caisse"],"answer":0},{"emoji":"🧀","concept":"sección / pasillo (rayon)","options":["un chariot","un rayon","une allée"],"answer":1},{"emoji":"🛒","concept":"carrito de compras","options":["un panier","un chariot","un sac"],"answer":1},{"emoji":"🧺","concept":"cesta","options":["un panier","un chariot","un sac"],"answer":0},{"emoji":"📝","concept":"lista de compras","options":["une étiquette","une liste de courses","une marque"],"answer":1},{"emoji":"🎉","concept":"oferta / promoción","options":["une promotion","une réduction","les soldes"],"answer":0},{"emoji":"📉","concept":"descuento (%)","options":["une offre","une réduction","une étiquette"],"answer":1},{"emoji":"📅","concept":"fecha de caducidad","options":["la date de péremption","l'étiquette","la qualité"],"answer":0},{"emoji":"🥖","concept":"pan fresco (frais)","options":["surgelé","frais","bio"],"answer":1},{"emoji":"🧊","concept":"congelado","options":["frais","surgelé","bio"],"answer":1},{"emoji":"🌿","concept":"ecológico / orgánico","options":["bio","frais","cher"],"answer":0},{"emoji":"❓","concept":"¿Dónde está…?","options":["Je cherche…","Où se trouve… ?","Il y a…"],"answer":1},{"emoji":"🔎","concept":"Busco…","options":["Je cherche…","Où se trouve… ?","Il n'y a pas de…"],"answer":0},{"emoji":"✅","concept":"Hay…","options":["Il y a…","Il n'y a pas de…","Je cherche…"],"answer":0},{"emoji":"🚫","concept":"No hay…","options":["Il y a…","Il n'y a pas de…","Où se trouve… ?"],"answer":1}],"grammar":[{"formula":"IL Y A + article + nom = « Hay… »","use":"Confirmar la existencia: « Il y a du pain frais. » / « Il y a des promotions. »"},{"formula":"IL N'Y A PAS DE + nom (sin artículo)","use":"Negar la existencia: « Il n'y a pas de lait. » / « Il n'y a pas d'œufs. »"},{"formula":"OÙ SE TROUVE + article + nom ?","use":"Preguntar por la ubicación de una sección: « Où se trouve le rayon fromages ? »"},{"formula":"JE CHERCHE + article + nom","use":"Explicar qué buscas: « Je cherche les produits surgelés. »"}],"vocabGames":{"reading":[{"title":"Texte · Au supermarché","text":"Camille entre dans un grand supermarché à Lyon. Elle prend un chariot et sort sa liste de courses. Elle cherche d'abord le rayon fromages, mais elle ne le trouve pas. Elle demande à un employé : « Excusez-moi, où se trouve le rayon fromages ? » L'employé répond : « C'est au fond du magasin, à gauche des surgelés. » Camille voit qu'il y a une promotion sur le camembert cette semaine — 30 % de réduction ! Elle regarde aussi la date de péremption avant d'acheter. À la caisse, elle demande un sac réutilisable, mais l'employée dit : « Il n'y a pas de sacs gratuits, ils coûtent 50 centimes. » Camille paie et part contente : elle a trouvé tous les produits de sa liste.","questions":[{"q":"¿Dónde está el rayon fromages?","options":["A la derecha de la entrada.","Al fondo del supermercado, a la izquierda de los congelados.","Cerca de las cajas."],"answer":1},{"q":"¿Qué producto está en promoción esta semana?","options":["El pan fresco","El camembert","Los productos bio"],"answer":1},{"q":"¿Qué le dice la empleada de la caja sobre las bolsas?","options":["Que son gratis.","Que no hay bolsas gratuitas, cuestan 50 céntimos.","Que solo hay bolsas de papel."],"answer":1}]}],"listening":[{"audio":"Où se trouve le rayon fromages, s'il vous plaît ?","question":"¿Qué está preguntando el cliente?","options":["Cuánto cuesta el queso","Dónde está la sección de quesos","Si hay queso fresco"],"answer":1},{"audio":"Il y a du pain frais aujourd'hui ?","question":"¿Qué quiere saber?","options":["Si el pan es congelado.","Si hay pan fresco hoy.","Dónde está el pan."],"answer":1},{"audio":"Il n'y a pas de lait demi-écrémé.","question":"¿Qué acaba de decir?","options":["Que hay leche semidesnatada.","Que no hay leche semidesnatada.","Que prefiere la leche entera."],"answer":1},{"audio":"Je cherche les produits surgelés.","question":"¿Qué está buscando?","options":["Productos frescos","Productos congelados","Productos bio"],"answer":1},{"audio":"Il y a une promotion sur le camembert.","question":"¿Qué información da?","options":["Que el camembert está agotado.","Que hay una promoción sobre el camembert.","Que el camembert es caro."],"answer":1}],"speaking":[{"situation":"Pregunta dónde está la sección de quesos usando « Où se trouve… ? ».","expected":"Où se trouve le rayon fromages, s'il vous plaît ?"},{"situation":"Pregunta si hay pan fresco hoy.","expected":"Il y a du pain frais aujourd'hui ?"},{"situation":"Di que no hay leche desnatada en el pasillo.","expected":"Il n'y a pas de lait demi-écrémé."},{"situation":"Explica que buscas los productos congelados.","expected":"Je cherche les produits surgelés."},{"situation":"Pregunta si hay promociones esta semana.","expected":"Il y a des promotions cette semaine ?"}],"writing":[{"prompt":"Traduce: '¿Dónde está la sección de quesos?'","answer":"Où se trouve le rayon fromages ?"},{"prompt":"Completa: « ______ des promotions cette semaine ? »","answer":"Il y a"},{"prompt":"Traduce: 'No hay pan fresco.'","answer":"Il n'y a pas de pain frais."},{"prompt":"Ordena: [ je / les / cherche / surgelés / produits ]","answer":"Je cherche les produits surgelés."},{"prompt":"Corrige: « Il n'y a pas du lait. »","answer":"Il n'y a pas de lait."}]},"clesReading":{"title":"Lecture · Il y a / Il n'y a pas de au supermarché","text":"Théo fait ses courses dans un supermarché près de chez lui. Il regarde sa liste : du pain, du lait, des œufs et du fromage. Au rayon boulangerie, il voit qu'il y a du pain frais ce matin. Super ! Au rayon crémerie, il cherche du lait demi-écrémé, mais il n'y a pas de lait demi-écrémé aujourd'hui — il prend du lait entier à la place. Ensuite, il va au rayon fromages : il y a une promotion sur le camembert. Il en prend deux. À la caisse, il demande un sac, mais la caissière répond : « Il n'y a pas de sacs gratuits, ils coûtent 50 centimes. » Théo sourit : « Pas de problème, j'ai mon sac réutilisable. »","questions":[{"q":"¿Qué estructura usa el texto para confirmar existencia?","options":["« Je voudrais… »","« Il y a… » + artículo + sustantivo.","« Où se trouve… ? »"],"answer":1},{"q":"¿Cómo se niega la existencia en francés?","options":["« Il n'y a pas du + nom » (con artículo definido).","« Il n'y a pas de + nom » (sin artículo).","« Il n'y a pas des + nom »."],"answer":1},{"q":"¿Cuál es el error frecuente que hay que evitar?","options":["« Il n'y a pas de lait » (✓) → « Il n'y a pas du lait » (❌).","« Il y a du lait » (❌) → « Il y a de lait » (✓).","« Il n'y a pas de lait » (❌) → « Il y a pas lait » (✓)."],"answer":0}]},"clesGames":{"listening":[{"audio":"Il y a du pain frais aujourd'hui.","question":"¿Qué estructura reconoces?","options":["Il n'y a pas de + nom (negativo).","Il y a + article + nom (afirmativo).","Où se trouve + article + nom ?"],"answer":1},{"audio":"Il n'y a pas de lait demi-écrémé.","question":"¿Cuál es la traducción correcta?","options":["Hay leche semidesnatada.","No hay leche semidesnatada.","Prefiero la leche semidesnatada."],"answer":1},{"audio":"Il n'y a pas d'œufs bio.","question":"¿Por qué se dice « d' » y no « de » ?","options":["Porque el sustantivo empieza por vocal.","Porque es un error, debería ser « de ».","Porque « œufs » es masculino."],"answer":0},{"audio":"Il y a des promotions cette semaine.","question":"¿Qué expresa esta frase?","options":["Que no hay promociones esta semana.","Que hay promociones esta semana.","Que las promociones son caras."],"answer":1},{"audio":"Il n'y a pas du pain frais.","question":"Esta frase tiene un error. ¿Cuál?","options":["Debería decir « Il n'y a pas de pain frais » — en negativo, el artículo desaparece.","Debería decir « Il y a pas du pain frais ».","Está correcta."],"answer":0}],"speaking":[{"situation":"Confirma que hay pan fresco hoy.","expected":"Il y a du pain frais aujourd'hui."},{"situation":"Niega la existencia de leche semidesnatada.","expected":"Il n'y a pas de lait demi-écrémé."},{"situation":"Confirma que hay promociones esta semana.","expected":"Il y a des promotions cette semaine."},{"situation":"Niega la existencia de huevos bio (¡atención a la elisión!).","expected":"Il n'y a pas d'œufs bio."},{"situation":"Pregunta si hay crema fresca.","expected":"Il y a de la crème fraîche ?"}],"writing":[{"prompt":"Transforma a negativo: « Il y a du pain. »","answer":"Il n'y a pas de pain."},{"prompt":"Transforma a negativo: « Il y a des œufs. »","answer":"Il n'y a pas d'œufs."},{"prompt":"Transforma a negativo: « Il y a de la crème. »","answer":"Il n'y a pas de crème."},{"prompt":"Corrige: « Il n'y a pas du lait. »","answer":"Il n'y a pas de lait."},{"prompt":"Completa el diálogo: « Client: ______ du pain frais aujourd'hui ? »","answer":"Il y a"}]},"defiSteps":[{"serveur":"Bonjour ! Bienvenue au supermarché. Je peux vous aider ?","hint":"Saluda al empleado y pregunta dónde está el rayon fromages usando « Où se trouve… ? ».","example":"Bonjour ! Excusez-moi, où se trouve le rayon fromages, s'il vous plaît ?"},{"serveur":"Le rayon fromages est au fond du magasin, à gauche des surgelés.","hint":"Da las gracias y pregunta si hay pan fresco hoy usando « Il y a… ? ».","example":"Merci beaucoup ! Et il y a du pain frais aujourd'hui ?"},{"serveur":"Oui, il y a du pain frais ce matin, au rayon boulangerie.","hint":"Pregunta por una segunda sección (por ejemplo boissons o produits bio) con « Où se trouve… ? ».","example":"Parfait. Et où se trouve le rayon des boissons, s'il vous plaît ?"},{"serveur":"Les boissons sont dans l'allée 5, à droite après les conserves.","hint":"Comenta que no hay bolsas en la caja o pregunta si hay promociones esta semana usando « Il n'y a pas de… » o « Il y a… ».","example":"D'accord. Il n'y a pas de sacs à la caisse ? Et il y a des promotions cette semaine ?"},{"serveur":"Il y a des promotions sur le fromage et les fruits bio. Autre chose ?","hint":"Agradece y despídete con « Merci » y « Bonne journée ».","example":"Non, c'est tout, merci beaucoup pour votre aide. Bonne journée !"}],"defiCriteria":["Saluda y usa fórmulas de cortesía apropiadas al contexto.","Emplea el vocabulario clave del día (Supermarché · Partie 1).","Aplica la estructura gramatical del día correctamente.","Responde a las preguntas del interlocutor sin cambiar al español.","Pide aclaración o repetición si no entiende algo.","Cierra la interacción con una despedida adecuada."],"tutor":{"role":"empleada de un supermercado francés; el alumno hace las compras","opener_fr":"Bonjour ! Je peux vous aider ? Vous cherchez quelque chose ?","opener_es":"¡Hola! ¿Puedo ayudarle? ¿Busca algo?","objectives":["Pregunta dónde está un producto (« Où est… ? »)","Pide una cantidad (« Je voudrais un kilo de… »)","Pregunta el precio"],"topic":"Au supermarché — hacer las compras"},"meta":{"label":"Jour 7 · Supermarché · Partie 1","headTitle":"Jour 7 · Supermarché · Partie 1 — Liberté","headDesc":"Jour 7 · Supermarché · Partie 1: lección completa del programa Liberté.","week":2,"weekEmoji":"🛒","intro":"Bienvenue au Jour 7 ! Au supermarché. Respire, tu es prêt.","introSub":"Au supermarché.","clesSub":"Trouver les rayons et demander de l'aide.","defiTitle":"Supermarché · Partie 1","defiSubtitle":"Haz la compra en el supermercado.","defiAvatar":"🛒"}}$rich$::jsonb)
