INSERT INTO public.authored_days (day_id, title, subtitle, status, rich) VALUES (8, 'Jour 8 · Faire les courses', 'Quantités, prix et paiement.', 'draft', $rich${"gym":"https://www.youtube.com/embed/AdJPOTR-CdU","vocabulary":[{"fr":"de la lessive","es":"detergente","example":"Je dois acheter de la lessive.","emoji":"🧺"},{"fr":"du dentifrice","es":"pasta de dientes","example":"Il n'y a plus de dentifrice.","emoji":"🦷"},{"fr":"du jambon","es":"jamón","example":"Je prends 200g de jambon.","emoji":"🥓"},{"fr":"un yaourt","es":"un yogur","example":"Je voudrais des yaourts nature.","emoji":"🥛"},{"fr":"de la crème","es":"nata / crema","example":"J'ai besoin de crème fraîche.","emoji":"🥛"},{"fr":"des œufs","es":"huevos","example":"Une boîte de 6 œufs, s'il vous plaît.","emoji":"🥚"},{"fr":"de la farine","es":"harina","example":"Je dois acheter de la farine pour la recette.","emoji":"🌾"},{"fr":"de la moutarde","es":"mostaza","example":"Vous avez de la moutarde de Dijon ?","emoji":"🟡"},{"fr":"du sel","es":"sal","example":"Je n'ai plus de sel à la maison.","emoji":"🧂"},{"fr":"de l'huile","es":"aceite","example":"De l'huile d'olive, s'il vous plaît.","emoji":"🫒"},{"fr":"du vinaigre","es":"vinagre","example":"Du vinaigre balsamique, c'est au rayon condiments.","emoji":"🧴"},{"fr":"des biscuits","es":"galletas","example":"Je dois acheter des biscuits pour le goûter.","emoji":"🍪"},{"fr":"des lentilles","es":"lentejas","example":"Des lentilles vertes, c'est très bon.","emoji":"🫘"},{"fr":"des céréales","es":"cereales","example":"Je prends des céréales sans sucre.","emoji":"🥣"},{"fr":"des fruits","es":"frutas","example":"Je dois acheter des fruits frais.","emoji":"🍎"},{"fr":"des fruits secs","es":"frutos secos","example":"Des noix et des amandes, s'il vous plaît.","emoji":"🥜"},{"fr":"de la dinde","es":"pavo","example":"Je voudrais de la dinde pour ce soir.","emoji":"🦃"},{"fr":"des crevettes","es":"camarones / gambas","example":"Des crevettes fraîches, vous en avez ?","emoji":"🦐"},{"fr":"de la charcuterie","es":"embutidos / fiambres","example":"Un peu de charcuterie variée, s'il vous plaît.","emoji":"🥩"},{"fr":"un pack d'eau","es":"un pack de agua","example":"Je dois prendre un pack d'eau.","emoji":"💧"},{"fr":"de l'eau","es":"agua","example":"De l'eau plate ou gazeuse ?","emoji":"🚰"},{"fr":"du jus","es":"zumo / jugo","example":"Du jus d'orange sans sucre ajouté.","emoji":"🧃"},{"fr":"de la bière","es":"cerveza","example":"De la bière artisanale, vous en avez ?","emoji":"🍺"},{"fr":"du vin","es":"vino","example":"Du vin rouge de la région, s'il vous plaît.","emoji":"🍷"},{"fr":"du savon","es":"jabón","example":"Je dois acheter du savon liquide.","emoji":"🧼"},{"fr":"du shampooing","es":"champú","example":"Quel shampooing recommandez-vous ?","emoji":"🧴"},{"fr":"du papier toilette","es":"papel higiénico","example":"Il n'y a plus de papier toilette à la maison !","emoji":"🧻"},{"fr":"du nettoyant","es":"producto de limpieza","example":"Du nettoyant multi-surfaces, c'est pratique.","emoji":"🧽"},{"fr":"Je dois acheter…","es":"Debo comprar…","example":"Je dois acheter du lait et des œufs.","emoji":"🛒"},{"fr":"du soda","es":"refresco","example":"Je voudrais du soda, pas trop sucré.","emoji":"🥤"}],"flashQuiz":[{"emoji":"🥚","concept":"huevos (partitivo)","options":["du œufs","des œufs","de l'œufs"],"answer":1},{"emoji":"🥛","concept":"leche (partitivo)","options":["du lait","de la lait","des lait"],"answer":0},{"emoji":"🫒","concept":"aceite (partitivo)","options":["du huile","de la huile","de l'huile"],"answer":2},{"emoji":"🌾","concept":"harina (partitivo)","options":["du farine","de la farine","des farine"],"answer":1},{"emoji":"🍪","concept":"galletas (partitivo)","options":["du biscuits","de la biscuits","des biscuits"],"answer":2},{"emoji":"🧂","concept":"sal (partitivo)","options":["du sel","de la sel","des sel"],"answer":0},{"emoji":"🍷","concept":"vino (partitivo)","options":["du vin","de la vin","des vin"],"answer":0},{"emoji":"🧻","concept":"papel higiénico","options":["du papier toilette","de la papier","des papier"],"answer":0},{"emoji":"🛒","concept":"'Debo comprar…'","options":["Je veux acheter","Je dois acheter","J'achète"],"answer":1},{"emoji":"🦃","concept":"pavo (partitivo)","options":["du dinde","de la dinde","des dinde"],"answer":1},{"emoji":"🥩","concept":"embutidos (partitivo)","options":["du charcuterie","de la charcuterie","des charcuterie"],"answer":1},{"emoji":"💧","concept":"un pack de agua","options":["un pack de l'eau","un pack d'eau","un pack des eau"],"answer":1}],"grammar":[{"formula":"JE DOIS + INFINITIF = « Debo… »","use":"Expresar una obligación o necesidad: « Je dois acheter du lait. »"},{"formula":"TU DOIS + INFINITIF","use":"« Tu dois valider ton ticket à la caisse. »"},{"formula":"IL / ELLE DOIT + INFINITIF","use":"« Elle doit passer à la boulangerie. »"},{"formula":"NOUS DEVONS · VOUS DEVEZ · ILS DOIVENT","use":"« Nous devons prendre du pain. » / « Vous devez payer à la caisse. »"}],"vocabGames":{"reading":[{"title":"Texte · Faire les courses","text":"Samedi matin, Julie prépare sa liste de courses pour toute la semaine. Elle regarde le frigo : il n'y a plus de lait, plus d'œufs et plus de beurre. Dans le placard, il n'y a plus de farine ni de sucre. Elle écrit : « Je dois acheter du lait, des œufs, de la farine, du beurre et du sucre. » Puis elle pense aux produits d'hygiène : elle doit aussi prendre du shampooing, du savon et du papier toilette. Au supermarché, elle voit qu'il y a une promotion sur la charcuterie : elle prend du jambon et un peu de dinde. Pour la fête du dimanche, elle achète aussi du vin rouge et un pack d'eau. À la caisse, elle paie 87 euros — sa liste était bien complète !","questions":[{"q":"¿Qué debe comprar Julie del frigo?","options":["Solo leche y huevos.","Leche, huevos y mantequilla.","Solo mantequilla y harina."],"answer":1},{"q":"¿Qué productos de higiene añade a la lista?","options":["Shampooing, savon y papier toilette.","Solo shampooing y dentifrice.","Nettoyant y lessive."],"answer":0},{"q":"¿Qué compra para la fiesta del domingo?","options":["Del vino tinto y un pack de agua.","Cerveza y zumo.","Solo vino blanco."],"answer":0}]}],"listening":[{"audio":"Je dois acheter du lait et des œufs.","question":"¿Qué debe comprar la persona?","options":["Leche y huevos.","Leche y harina.","Solo huevos."],"answer":0},{"audio":"Il n'y a plus de dentifrice à la maison.","question":"¿Qué falta en la casa?","options":["Papel higiénico.","Pasta de dientes.","Jabón."],"answer":1},{"audio":"Je voudrais 200g de jambon, s'il vous plaît.","question":"¿Qué pide?","options":["200g de pavo.","200g de jamón.","200g de charcutería."],"answer":1},{"audio":"Nous devons prendre un pack d'eau.","question":"¿Qué deben hacer?","options":["Comprar un pack de agua.","Comprar vino.","Comprar zumo."],"answer":0},{"audio":"Vous devez passer à la caisse.","question":"¿Qué le indican al cliente?","options":["Que debe pagar en caja.","Que hay una promoción.","Que debe salir por la puerta."],"answer":0}],"speaking":[{"situation":"Di que debes comprar leche y huevos.","expected":"Je dois acheter du lait et des œufs."},{"situation":"Pide 200g de jamón con cortesía.","expected":"Je voudrais 200g de jambon, s'il vous plaît."},{"situation":"Explica que debes tomar un pack de agua.","expected":"Je dois prendre un pack d'eau."},{"situation":"Di que ya no hay pasta de dientes en casa.","expected":"Il n'y a plus de dentifrice à la maison."},{"situation":"Di que debes comprar aceite de oliva.","expected":"Je dois acheter de l'huile d'olive."}],"writing":[{"prompt":"Traduce: 'Debo comprar leche.'","answer":"Je dois acheter du lait."},{"prompt":"Completa: « Je dois acheter ______ œufs. » (partitivo)","answer":"des"},{"prompt":"Completa: « Je dois acheter ______ farine. » (partitivo)","answer":"de la"},{"prompt":"Completa: « Je dois acheter ______ huile d'olive. » (partitivo)","answer":"de l'"},{"prompt":"Corrige: « Je dois acheter de pain. »","answer":"Je dois acheter du pain."}]},"clesReading":{"title":"Lecture · Devoir + infinitif","text":"Le samedi, chez les Martin, tout le monde a une mission. « Papa, tu dois passer au supermarché », dit maman. « Nous devons acheter du lait, des œufs et de la farine pour le gâteau. » Papa répond : « D'accord, mais Léa doit venir avec moi — elle doit apprendre à faire les courses. » Léa proteste un peu, mais elle prend la liste. Au magasin, Papa explique : « Regarde bien les étiquettes. Tu dois vérifier la date de péremption et la marque. » À la caisse, Léa demande : « Je dois payer par carte ou en espèces ? » Papa sourit : « Comme tu veux — l'important, c'est que tu apprennes. »","questions":[{"q":"¿Qué estructura se usa para expresar una obligación en francés?","options":["Vouloir + infinitivo.","Devoir (conjugado) + infinitivo.","Aller + infinitivo."],"answer":1},{"q":"¿Cómo se dice « Debemos comprar leche » en francés?","options":["Nous voulons acheter du lait.","Nous devons acheter du lait.","Nous allons du lait."],"answer":1},{"q":"¿Cuál es el error frecuente que hay que evitar?","options":["« Je dois acheter du pain » (✓) → « Je dois acheter de pain » (❌).","« Je dois acheter du pain » (❌) → « Je dois acheter de pain » (✓).","No se puede usar devoir con partitivos."],"answer":0}]},"clesGames":{"listening":[{"audio":"Vous devez acheter des légumes.","question":"¿Qué estructura reconoces?","options":["Vouloir + infinitivo.","Devoir (conjugado) + infinitivo.","Aller + infinitivo."],"answer":1},{"audio":"Il doit passer à la caisse.","question":"¿Qué debe hacer?","options":["Debe salir del supermercado.","Debe pasar por la caja.","Debe pagar con tarjeta."],"answer":1},{"audio":"Nous devons prendre du lait.","question":"¿Cuál es la traducción correcta?","options":["Queremos leche.","Debemos tomar / comprar leche.","Vamos a por leche."],"answer":1},{"audio":"Tu dois valider ton ticket.","question":"¿Qué indica la frase?","options":["Que puedes validar el tique.","Que debes validar el tique.","Que ya has validado el tique."],"answer":1},{"audio":"Je dois acheter de pain.","question":"Esta frase tiene un error. ¿Cuál?","options":["Debería decir « Je dois acheter du pain » — con partitivo « du ».","Debería decir « Je dois du pain acheter ».","Está correcta."],"answer":0}],"speaking":[{"situation":"Di « Debo comprar leche » con devoir + infinitivo.","expected":"Je dois acheter du lait."},{"situation":"Di « Debes pasar por la caja » (tú).","expected":"Tu dois passer à la caisse."},{"situation":"Di « Ella debe tomar / coger cereales ».","expected":"Elle doit prendre des céréales."},{"situation":"Di « Debemos comprar huevos ».","expected":"Nous devons acheter des œufs."},{"situation":"Di « Ustedes deben pagar en caja ».","expected":"Vous devez payer à la caisse."}],"writing":[{"prompt":"Completa: « (vous) ______ acheter des légumes. »","answer":"devez"},{"prompt":"Completa: « (il) ______ passer à la caisse. »","answer":"doit"},{"prompt":"Completa: « (nous) ______ prendre du lait. »","answer":"devons"},{"prompt":"Ordena: [ dois / je / acheter / lait / du ]","answer":"Je dois acheter du lait."},{"prompt":"Corrige: « Je dois acheter de pain. »","answer":"Je dois acheter du pain."}]},"defiSteps":[{"serveur":"Bonjour ! Bienvenue. Vous cherchez quelque chose en particulier ?","hint":"Saluda y explica que debes hacer la compra semanal usando « Je dois faire les courses ».","example":"Bonjour ! Oui, je dois faire les courses de la semaine. J'ai une longue liste."},{"serveur":"Très bien ! Par quoi commencez-vous ?","hint":"Menciona 3 productos que debes comprar con « Je dois acheter… » + partitivos (du / de la / des / de l').","example":"Je dois acheter du lait, des œufs et de la farine pour une recette."},{"serveur":"Parfait. Il y a des promotions sur les produits laitiers cette semaine.","hint":"Añade 3 productos más (higiene o bebidas) usando « Je dois prendre… » + partitivos.","example":"Super ! Je dois aussi prendre du shampooing, du papier toilette et un pack d'eau."},{"serveur":"Vous voulez quelque chose au rayon boucherie ?","hint":"Pide carne o embutidos con partitivos correctos (de la dinde, du jambon, de la charcuterie…).","example":"Oui, je dois acheter de la dinde et un peu de charcuterie pour le pique-nique."},{"serveur":"Très bien. Passez à la caisse quand vous êtes prêt(e).","hint":"Agradece y despídete con « Merci » y « Bonne journée ».","example":"Merci beaucoup pour votre aide. Bonne journée !"}],"defiCriteria":["Saluda y usa fórmulas de cortesía apropiadas al contexto.","Emplea el vocabulario clave del día (Faire les courses).","Aplica la estructura gramatical del día correctamente.","Responde a las preguntas del interlocutor sin cambiar al español.","Pide aclaración o repetición si no entiende algo.","Cierra la interacción con una despedida adecuada."],"tutor":{"role":"vendedora en un marché francés; puesto de frutas y verduras","opener_fr":"Bonjour ! Regardez mes beaux fruits ! Qu'est-ce qu'il vous faut ?","opener_es":"¡Hola! ¡Mire mis lindas frutas! ¿Qué necesita?","objectives":["Pide dos productos con cantidades","Pregunta cuánto cuesta (« Combien coûte… ? »)","Repite el precio para confirmar y paga"],"topic":"Les courses — cantidades y precios"},"meta":{"label":"Jour 8 · Faire les courses","headTitle":"Jour 8 · Faire les courses — Liberté","headDesc":"Jour 8 · Faire les courses: lección completa del programa Liberté.","week":2,"weekEmoji":"🧺","intro":"Bienvenue au Jour 8 ! Faire les courses. Respire, tu es prêt.","introSub":"Faire les courses.","clesSub":"Quantités, prix et paiement.","defiTitle":"Faire les courses","defiSubtitle":"Cantidades y precios en el mercado.","defiAvatar":"🧺"}}$rich$::jsonb)
ON CONFLICT (day_id) DO NOTHING;
INSERT INTO public.authored_days (day_id, title, subtitle, status, rich) VALUES (9, 'Jour 9 · Le métro & les transports', 'Acheter un ticket et demander la direction.', 'draft', $rich${"gym":"https://www.youtube.com/embed/AdJPOTR-CdU","vocabulary":[{"fr":"le métro","es":"el metro","example":"Je prends le métro chaque matin.","emoji":"🚇"},{"fr":"le bus","es":"el autobús","example":"Le bus 73 va à l'Opéra.","emoji":"🚌"},{"fr":"le tram","es":"el tranvía","example":"Le tram passe toutes les 5 minutes.","emoji":"🚊"},{"fr":"le train","es":"el tren","example":"Je prends le train pour Lyon.","emoji":"🚆"},{"fr":"une station","es":"una estación (metro/bus)","example":"La station Châtelet est très grande.","emoji":"🏙️"},{"fr":"un arrêt","es":"una parada","example":"Je descends à l'arrêt suivant.","emoji":"🛑"},{"fr":"une ligne","es":"una línea","example":"Je dois changer de ligne ?","emoji":"🧭"},{"fr":"la direction","es":"la dirección / sentido","example":"Direction Châtelet — c'est le bon sens ?","emoji":"➡️"},{"fr":"une correspondance","es":"un transbordo","example":"Il faut prendre une correspondance à Nation.","emoji":"🔁"},{"fr":"un billet","es":"un billete","example":"Un billet, s'il vous plaît.","emoji":"🎟️"},{"fr":"un ticket","es":"un ticket","example":"N'oubliez pas de valider votre ticket.","emoji":"🎫"},{"fr":"un carnet","es":"un abono de viajes","example":"Un carnet de 10 tickets, s'il vous plaît.","emoji":"📇"},{"fr":"un abonnement","es":"un abono mensual","example":"J'ai un abonnement mensuel.","emoji":"💳"},{"fr":"un aller simple","es":"un billete de ida","example":"Un aller simple pour Versailles, s'il vous plaît.","emoji":"➡️"},{"fr":"un aller-retour","es":"un billete de ida y vuelta","example":"Un aller-retour Paris-Lyon, s'il vous plaît.","emoji":"🔄"},{"fr":"valider","es":"validar","example":"N'oubliez pas de valider votre billet !","emoji":"✅"},{"fr":"un quai","es":"un andén","example":"Le train part du quai numéro 3.","emoji":"🚉"},{"fr":"une voie","es":"una vía","example":"Voie B — départ dans 5 minutes.","emoji":"🛤️"},{"fr":"le départ","es":"la salida (hora)","example":"Le départ est à 14h30.","emoji":"🕒"},{"fr":"l'arrivée","es":"la llegada","example":"L'arrivée est prévue à 16h.","emoji":"🕓"},{"fr":"un horaire","es":"un horario","example":"Je regarde les horaires en ligne.","emoji":"📅"},{"fr":"un retard","es":"un retraso","example":"Il y a un retard de 10 minutes.","emoji":"⏰"},{"fr":"une annulation","es":"una cancelación","example":"Il y a une annulation sur la ligne 4.","emoji":"❌"},{"fr":"prochain","es":"próximo / siguiente","example":"Le prochain métro arrive dans 2 minutes.","emoji":"⏭️"},{"fr":"direct","es":"directo","example":"Ce train est direct — pas de correspondance.","emoji":"🎯"},{"fr":"en métro","es":"en metro","example":"J'y vais en métro.","emoji":"🚇"},{"fr":"en bus","es":"en autobús","example":"Je préfère y aller en bus.","emoji":"🚌"},{"fr":"à pied","es":"a pie","example":"C'est à 10 minutes à pied.","emoji":"🚶"},{"fr":"composter","es":"picar el billete","example":"N'oubliez pas de composter votre ticket.","emoji":"🖊️"},{"fr":"dernier","es":"último","example":"C'est le dernier métro à minuit.","emoji":"🌙"}],"flashQuiz":[{"emoji":"🚇","concept":"en métro (preposición)","options":["à métro","en métro","par métro"],"answer":1},{"emoji":"🚶","concept":"a pie (preposición)","options":["en pied","à pied","par pied"],"answer":1},{"emoji":"🚴","concept":"en bicicleta (preposición)","options":["en vélo","à vélo","par vélo"],"answer":1},{"emoji":"🚆","concept":"en tren (formal)","options":["à train","en train","par le train"],"answer":2},{"emoji":"🚌","concept":"en autobús","options":["à bus","en bus","par bus"],"answer":1},{"emoji":"🎫","concept":"'validar el ticket'","options":["valider le ticket","composter le train","acheter le quai"],"answer":0},{"emoji":"🚉","concept":"'el andén'","options":["une voie","un quai","une ligne"],"answer":1},{"emoji":"🔁","concept":"'un transbordo'","options":["une direction","une correspondance","un aller-retour"],"answer":1},{"emoji":"🎟️","concept":"'un billete de ida'","options":["un aller-retour","un aller simple","un abonnement"],"answer":1},{"emoji":"⏰","concept":"'un retraso'","options":["une annulation","un retard","un horaire"],"answer":1},{"emoji":"⏭️","concept":"'el próximo metro'","options":["le dernier métro","le prochain métro","le direct métro"],"answer":1},{"emoji":"📇","concept":"'un abono de 10 tickets'","options":["un abonnement","un carnet","un aller-retour"],"answer":1}],"grammar":[{"formula":"EN + VÉHICULE FERMÉ","use":"Vehículo cerrado : en métro · en bus · en voiture · en avion · en bateau."},{"formula":"À + SANS MOTEUR / PETIT","use":"Sin motor o pequeño : à pied · à vélo · à moto."},{"formula":"PAR + MODE FORMEL","use":"Modo formal (textos, reservas) : par le train · par avion."},{"formula":"⚠️ ERREURS À ÉVITER","use":"« en pied » ❌ · « en vélo » ❌ → siempre « à pied » ✓ · « à vélo » ✓."}],"vocabGames":{"reading":[{"title":"Texte · Dans le métro parisien","text":"Voyageur : « Excusez-moi, pour aller à la Tour Eiffel, je dois prendre quelle ligne ? » Passager : « Prenez la ligne 6, direction Nation. Descendez à Bir-Hakeim. » Voyageur : « Je dois faire une correspondance ? » Passager : « Non, c'est direct depuis ici. Mais n'oubliez pas de valider votre ticket ! » Voyageur : « Merci beaucoup. C'est loin ? » Passager : « Non, c'est à 4 arrêts. Environ 8 minutes. »","questions":[{"q":"¿Qué línea debe tomar el viajero?","options":["La línea 4, dirección Châtelet.","La línea 6, dirección Nation.","La línea 1, dirección Vincennes."],"answer":1},{"q":"¿Dónde debe bajar?","options":["En Châtelet.","En Nation.","En Bir-Hakeim."],"answer":2},{"q":"¿Debe hacer un transbordo?","options":["Sí, en Nation.","No, es directo.","Sí, en Bir-Hakeim."],"answer":1}]}],"listening":[{"audio":"Prenez la ligne 6, direction Nation.","question":"¿Qué línea y dirección debe tomar?","options":["Ligne 6, direction Nation.","Ligne 4, direction Châtelet.","Ligne 1, direction Défense."],"answer":0},{"audio":"N'oubliez pas de valider votre ticket.","question":"¿Qué debe hacer con el ticket?","options":["Comprarlo.","Validarlo.","Tirarlo."],"answer":1},{"audio":"Le prochain métro arrive dans 2 minutes.","question":"¿Cuándo llega el próximo metro?","options":["En 2 minutos.","En 10 minutos.","En 20 minutos."],"answer":0},{"audio":"Un aller-retour Paris-Lyon, s'il vous plaît.","question":"¿Qué tipo de billete pide?","options":["Un billete de ida.","Un billete de ida y vuelta.","Un abono mensual."],"answer":1},{"audio":"Il y a un retard de 10 minutes sur la ligne 4.","question":"¿Qué ocurre en la línea 4?","options":["Una cancelación.","Un retraso de 10 minutos.","Un cambio de anden."],"answer":1}],"speaking":[{"situation":"Pide un billete de ida para Versailles con cortesía.","expected":"Je voudrais un aller simple pour Versailles, s'il vous plaît."},{"situation":"Pregunta qué línea tomar para ir a la Torre Eiffel.","expected":"Pour aller à la Tour Eiffel, je dois prendre quelle ligne ?"},{"situation":"Di « No olvide validar su ticket ».","expected":"N'oubliez pas de valider votre ticket."},{"situation":"Di que vas al trabajo en metro.","expected":"Je vais au travail en métro."},{"situation":"Di « Está a 10 minutos a pie ».","expected":"C'est à 10 minutes à pied."}],"writing":[{"prompt":"Traduce: 'Un billete de ida y vuelta, por favor.'","answer":"Un aller-retour, s'il vous plaît."},{"prompt":"Completa: « Je vais au travail ______ métro. »","answer":"en"},{"prompt":"Completa: « Je rentre ______ pied — c'est proche. »","answer":"à"},{"prompt":"Completa: « Il voyage ______ le train. »","answer":"par"},{"prompt":"Corrige: « Je vais en pied. »","answer":"Je vais à pied."}]},"clesReading":{"title":"Lecture · Prépositions de transport","text":"Marc habite à Paris et il utilise plusieurs moyens de transport chaque jour. Le matin, il va au travail en métro : c'est rapide et économique. Le midi, s'il fait beau, il rentre à pied pour déjeuner chez lui — c'est à 15 minutes. L'après-midi, quand il doit voir un client à l'autre bout de la ville, il prend un vélo en libre-service : il va donc à vélo. Le week-end, s'il rend visite à ses parents à Lyon, il voyage par le train — c'est confortable. Une fois par an, il part en vacances par avion. Marc dit toujours : « À pied, à vélo, en métro, par le train — chaque transport a son moment ! »","questions":[{"q":"¿Cómo va Marc al trabajo por la mañana?","options":["À pied.","En métro.","En voiture."],"answer":1},{"q":"¿Qué preposición se usa con « vélo » y « pied »?","options":["EN.","PAR.","À."],"answer":2},{"q":"¿Cómo viaja a Lyon los fines de semana?","options":["Par le train.","En bus.","En voiture."],"answer":0}]},"clesGames":{"listening":[{"audio":"Je vais au travail en métro.","question":"¿Qué preposición se usa con « métro »?","options":["à","en","par"],"answer":1},{"audio":"C'est à 10 minutes à pied.","question":"¿Qué preposición se usa con « pied »?","options":["à","en","par"],"answer":0},{"audio":"Il voyage par le train.","question":"¿Qué registro tiene esta frase?","options":["Informal.","Formal (reservas, textos).","Incorrecta."],"answer":1},{"audio":"Elle va à l'école à vélo.","question":"¿Cuál es la traducción correcta?","options":["Va en bicicleta a la escuela.","Va en autobús a la escuela.","Va a pie a la escuela."],"answer":0},{"audio":"Je vais en pied.","question":"Esta frase tiene un error. ¿Cuál?","options":["Debería decir « à pied » — con « à », no « en ».","Debería decir « par pied ».","Está correcta."],"answer":0}],"speaking":[{"situation":"Di « Voy al trabajo en metro » con la preposición correcta.","expected":"Je vais au travail en métro."},{"situation":"Di « Vuelvo a pie, está cerca ».","expected":"Je rentre à pied, c'est proche."},{"situation":"Di « Él viaja en tren » en registro formal.","expected":"Il voyage par le train."},{"situation":"Di « Ella va a la escuela en bicicleta ».","expected":"Elle va à l'école à vélo."},{"situation":"Di « Voy en avión a Roma ».","expected":"Je vais à Rome en avion."}],"writing":[{"prompt":"Completa: « Je vais au travail ______ métro. »","answer":"en"},{"prompt":"Completa: « Je rentre ______ pied — c'est proche. »","answer":"à"},{"prompt":"Completa: « Il voyage ______ le train. »","answer":"par"},{"prompt":"Completa: « Elle va à l'école ______ vélo. »","answer":"à"},{"prompt":"Corrige: « Je vais en pied. »","answer":"Je vais à pied."}]},"defiSteps":[{"serveur":"Bonjour ! Bienvenue au guichet. Je peux vous aider ?","hint":"Saluda y pide un billete usando « Je voudrais… » (aller simple o aller-retour).","example":"Bonjour ! Je voudrais un aller simple pour Versailles, s'il vous plaît."},{"serveur":"Très bien. Par le train ou par le RER ?","hint":"Elige el medio con la preposición correcta « par le train » o « par le RER ».","example":"Par le RER C, s'il vous plaît."},{"serveur":"Parfait. Voici votre billet. Autre chose ?","hint":"Pregunta qué línea debes tomar y en qué dirección para llegar a un lugar.","example":"Oui, pour aller à la Tour Eiffel, je dois prendre quelle ligne, et dans quelle direction ?"},{"serveur":"Prenez la ligne 6, direction Nation. Descendez à Bir-Hakeim.","hint":"Pregunta si es directo o si hay que hacer un transbordo.","example":"C'est direct ou je dois faire une correspondance ?"},{"serveur":"C'est direct. N'oubliez pas de valider votre ticket !","hint":"Agradece y despídete con cortesía.","example":"Merci beaucoup pour votre aide. Bonne journée !"}],"defiCriteria":["Saluda y usa fórmulas de cortesía apropiadas al contexto.","Emplea el vocabulario clave del día (Le métro & les transports).","Aplica la estructura gramatical del día correctamente.","Responde a las preguntas del interlocutor sin cambiar al español.","Pide aclaración o repetición si no entiende algo.","Cierra la interacción con una despedida adecuada."],"tutor":{"role":"agente del métro de Paris en la taquilla; el alumno necesita viajar","opener_fr":"Bonjour ! Je peux vous aider ? Où allez-vous ?","opener_es":"¡Hola! ¿Puedo ayudarle? ¿A dónde va?","objectives":["Compra un billete (« Je voudrais un ticket… »)","Pregunta cómo llegar a un lugar (« Pour aller à… ? »)","Confirma la línea o dirección y agradece"],"topic":"Le métro de Paris — transporte público"},"meta":{"label":"Jour 9 · Le métro & les transports","headTitle":"Jour 9 · Le métro & les transports — Liberté","headDesc":"Jour 9 · Le métro & les transports: lección completa del programa Liberté.","week":2,"weekEmoji":"🚇","intro":"Bienvenue au Jour 9 ! Le métro de Paris. Respire, tu es prêt.","introSub":"Le métro de Paris.","clesSub":"Acheter un ticket et demander la direction.","defiTitle":"Le métro & les transports","defiSubtitle":"Compra tu billete y encuentra tu línea.","defiAvatar":"🚇"}}$rich$::jsonb)
ON CONFLICT (day_id) DO NOTHING;
INSERT INTO public.authored_days (day_id, title, subtitle, status, rich) VALUES (10, 'Jour 10 · Taxi & ville à pied', 'Donner une adresse, demander le prix.', 'draft', $rich${"gym":"https://www.youtube.com/embed/AdJPOTR-CdU","vocabulary":[{"fr":"un taxi","es":"un taxi","example":"Je vais prendre un taxi — c'est trop loin.","emoji":"🚕"},{"fr":"un chauffeur","es":"un conductor","example":"Le chauffeur est très sympathique.","emoji":"🧑‍✈️"},{"fr":"une destination","es":"un destino","example":"Quelle est votre destination ?","emoji":"📍"},{"fr":"un trajet","es":"un trayecto","example":"Le trajet dure environ 20 minutes.","emoji":"🛣️"},{"fr":"la durée","es":"la duración","example":"Quelle est la durée du trajet ?","emoji":"⏱️"},{"fr":"le tarif","es":"la tarifa","example":"Quel est le tarif pour l'aéroport ?","emoji":"💶"},{"fr":"réserver","es":"reservar","example":"Je peux réserver un taxi en ligne ?","emoji":"📱"},{"fr":"descendre","es":"bajar","example":"Je descends ici, s'il vous plaît.","emoji":"⬇️"},{"fr":"monter","es":"subir","example":"Montez, je vous emmène.","emoji":"⬆️"},{"fr":"s'arrêter","es":"detenerse","example":"Arrêtez-vous ici, s'il vous plaît.","emoji":"🛑"},{"fr":"marcher","es":"caminar","example":"Je préfère marcher — c'est plus rapide.","emoji":"🚶"},{"fr":"le trottoir","es":"la acera","example":"Restez sur le trottoir.","emoji":"🛤️"},{"fr":"un passage clouté","es":"un paso de cebra","example":"Traversez au passage clouté.","emoji":"🦓"},{"fr":"un feu rouge / vert","es":"un semáforo","example":"Attendez le feu vert.","emoji":"🚦"},{"fr":"un carrefour","es":"un cruce","example":"Tournez à gauche au carrefour.","emoji":"🛣️"},{"fr":"une rue","es":"una calle","example":"C'est dans la rue de Rivoli.","emoji":"🏙️"},{"fr":"une avenue","es":"una avenida","example":"L'hôtel est sur l'avenue des Champs-Élysées.","emoji":"🌳"},{"fr":"un boulevard","es":"un bulevar","example":"Prenez le boulevard Haussmann.","emoji":"🏛️"},{"fr":"Excusez-moi…","es":"Disculpe…","example":"Excusez-moi, je cherche la gare.","emoji":"🙋"},{"fr":"Pour aller à…","es":"Para ir a…","example":"Pour aller à la gare, s'il vous plaît ?","emoji":"➡️"},{"fr":"C'est loin ?","es":"¿Está lejos?","example":"C'est loin d'ici ?","emoji":"❓"},{"fr":"C'est proche.","es":"Está cerca.","example":"Non, c'est très proche — 5 minutes à pied.","emoji":"📏"},{"fr":"Je dois changer ?","es":"¿Debo cambiar?","example":"Je dois changer de ligne ou c'est direct ?","emoji":"🔁"},{"fr":"Où est la sortie ?","es":"¿Dónde está la salida?","example":"Où est la sortie du métro ?","emoji":"🚪"},{"fr":"Prenez la ligne…","es":"Tome la línea…","example":"Prenez la ligne 1 jusqu'à la Défense.","emoji":"🚇"},{"fr":"en voiture","es":"en coche","example":"Je préfère aller en voiture.","emoji":"🚗"},{"fr":"par le train","es":"en tren (formal)","example":"Le meilleur c'est d'y aller par le train.","emoji":"🚆"},{"fr":"un compteur","es":"un taxímetro","example":"Regardez le compteur — c'est 12 euros.","emoji":"🧮"},{"fr":"un piéton","es":"un peatón","example":"Les piétons ont la priorité ici.","emoji":"🚶‍♀️"},{"fr":"un tunnel","es":"un túnel","example":"On passe par un tunnel sous la Seine.","emoji":"🕳️"}],"flashQuiz":[{"emoji":"🚕","concept":"'Voy a tomar un taxi'","options":["Je prends en taxi","Je prends le taxi","Je prends à taxi"],"answer":1},{"emoji":"🚇","concept":"'Tomo el metro'","options":["Je prends en métro","Je prends le métro","Je prends par métro"],"answer":1},{"emoji":"🚶","concept":"'A 10 minutos a pie'","options":["à 10 minutes en pied","à 10 minutes à pied","à 10 minutes par pied"],"answer":1},{"emoji":"❓","concept":"'¿Está lejos de aquí?'","options":["C'est proche d'ici ?","C'est loin d'ici ?","C'est où d'ici ?"],"answer":1},{"emoji":"🛑","concept":"'Deténgase aquí, por favor'","options":["Descendez ici, s'il vous plaît","Arrêtez-vous ici, s'il vous plaît","Montez ici, s'il vous plaît"],"answer":1},{"emoji":"💶","concept":"'la tarifa'","options":["le trajet","le tarif","le compteur"],"answer":1},{"emoji":"🧮","concept":"'el taxímetro'","options":["le trajet","le compteur","le tarif"],"answer":1},{"emoji":"🦓","concept":"'un paso de cebra'","options":["un carrefour","un passage clouté","un boulevard"],"answer":1},{"emoji":"🚦","concept":"'esperar el semáforo verde'","options":["attendre le feu rouge","attendre le feu vert","attendre le trottoir"],"answer":1},{"emoji":"🛣️","concept":"'un trayecto'","options":["une durée","un trajet","un tarif"],"answer":1},{"emoji":"➡️","concept":"'Para ir a la estación'","options":["Pour aller à la gare","Pour arriver la gare","À aller la gare"],"answer":0},{"emoji":"🚗","concept":"'en coche'","options":["à voiture","en voiture","par voiture"],"answer":1}],"grammar":[{"formula":"PRENDRE + LE/LA/L' + TRANSPORT","use":"Je prends le métro · le bus · le taxi · le train · l'avion."},{"formula":"⚠️ ERREUR À ÉVITER","use":"« Je prends en bus » ❌ → « Je prends le bus » ✓."},{"formula":"POUR ALLER À… ?","use":"Pregunta clave para pedir indicaciones : Pour aller à la gare, s'il vous plaît ?"},{"formula":"C'EST LOIN ? / C'EST À COMBIEN DE MINUTES ?","use":"Pregunta la distancia o el tiempo : C'est loin ? · C'est à 10 minutes à pied."}],"vocabGames":{"reading":[{"title":"Texte · En taxi à Paris","text":"Passager : « Bonjour, je voudrais aller à la gare du Nord, s'il vous plaît. » Chauffeur : « Bonjour ! Montez. Le trajet dure environ 20 minutes selon le trafic. » Passager : « C'est combien, à peu près ? » Chauffeur : « Entre 15 et 20 euros. Regardez le compteur. » Passager : « D'accord. Est-ce qu'on peut passer par les grands boulevards ? » Chauffeur : « Bien sûr. Vous êtes en visite à Paris ? » Passager : « Oui, c'est ma première fois. C'est magnifique ! » Chauffeur : « On arrive. Voilà la gare du Nord. Ça fait 17 euros. »","questions":[{"q":"¿Cuánto dura el trayecto?","options":["Unos 10 minutos.","Unos 20 minutos.","Unos 45 minutos."],"answer":1},{"q":"¿Cuánto cuesta el taxi al final?","options":["15 euros.","17 euros.","20 euros."],"answer":1},{"q":"¿Por dónde pide pasar el pasajero?","options":["Por los grandes bulevares.","Por el túnel.","Por la autopista."],"answer":0}]}],"listening":[{"audio":"Quelle est votre destination ?","question":"¿Qué pregunta el chofer?","options":["Cuál es su destino.","Cuál es su nombre.","Cuánto tiempo tiene."],"answer":0},{"audio":"Arrêtez-vous ici, s'il vous plaît.","question":"¿Qué pide el pasajero?","options":["Que acelere.","Que se detenga aquí.","Que dé la vuelta."],"answer":1},{"audio":"Le trajet dure environ 20 minutes.","question":"¿Cuánto dura el trayecto?","options":["10 minutos.","20 minutos.","45 minutos."],"answer":1},{"audio":"Regardez le compteur — c'est 12 euros.","question":"¿Qué debe mirar el pasajero?","options":["El GPS.","El taxímetro.","El reloj."],"answer":1},{"audio":"C'est à 5 minutes à pied.","question":"¿A qué distancia está?","options":["A 5 minutos en taxi.","A 5 minutos a pie.","A 5 minutos en metro."],"answer":1}],"speaking":[{"situation":"Pide ir a la Torre Eiffel en taxi con cortesía.","expected":"Bonjour, je voudrais aller à la Tour Eiffel, s'il vous plaît."},{"situation":"Pregunta cuánto dura el trayecto.","expected":"Quelle est la durée du trajet ?"},{"situation":"Pregunta la tarifa aproximada.","expected":"Quel est le tarif approximatif ?"},{"situation":"Pide al chofer que se detenga aquí.","expected":"Arrêtez-vous ici, s'il vous plaît."},{"situation":"Pregunta para ir a la estación con cortesía.","expected":"Excusez-moi, pour aller à la gare, s'il vous plaît ?"}],"writing":[{"prompt":"Traduce: 'Yo tomo el metro cada mañana.'","answer":"Je prends le métro chaque matin."},{"prompt":"Completa: « Je prends ______ taxi. »","answer":"le"},{"prompt":"Traduce: '¿Está lejos de aquí?'","answer":"C'est loin d'ici ?"},{"prompt":"Traduce: 'Deténgase aquí, por favor.'","answer":"Arrêtez-vous ici, s'il vous plaît."},{"prompt":"Corrige: « Je prends en bus. »","answer":"Je prends le bus."}]},"clesReading":{"title":"Lecture · Verbe prendre + questions pratiques","text":"À Paris, Sophie utilise différents moyens de transport selon la situation. Le matin, elle prend le métro pour aller au travail — c'est rapide et pas cher. Le midi, elle marche : « Il fait beau, je préfère aller à pied. » Quand elle est pressée ou qu'il pleut, elle prend un taxi. Elle dit toujours au chauffeur : « Bonjour, je voudrais aller à… , s'il vous plaît. Quelle est la durée du trajet ? » Le week-end, quand elle rend visite à ses parents, elle prend le train — c'est confortable. Pour trouver un lieu qu'elle ne connaît pas, elle demande : « Excusez-moi, pour aller à la gare, s'il vous plaît ? C'est loin d'ici ? » Sa règle d'or : jamais dire « je prends en bus » — toujours « je prends le bus » !","questions":[{"q":"¿Cómo va Sophie al trabajo por la mañana?","options":["Elle prend le taxi.","Elle prend le métro.","Elle va à pied."],"answer":1},{"q":"¿Cuál es la forma correcta con « prendre »?","options":["Je prends en bus.","Je prends le bus.","Je prends à bus."],"answer":1},{"q":"¿Qué pregunta clave usa para pedir indicaciones?","options":["« Où est le bus ? »","« Pour aller à… , s'il vous plaît ? »","« C'est combien ? »"],"answer":1}]},"clesGames":{"listening":[{"audio":"Je prends le métro chaque matin.","question":"¿Qué estructura se usa?","options":["prendre + en + transport","prendre + le/la/l' + transport","prendre + à + transport"],"answer":1},{"audio":"Pour aller à la gare, s'il vous plaît ?","question":"¿Qué pide el hablante?","options":["Indicaciones para ir a la estación.","El precio del tren.","La hora de salida."],"answer":0},{"audio":"C'est loin d'ici ?","question":"¿Qué pregunta?","options":["Si es caro.","Si está lejos.","Si es directo."],"answer":1},{"audio":"Je prends le taxi.","question":"¿Es correcta la frase?","options":["Sí, es correcta.","No, debería ser « je prends en taxi ».","No, debería ser « je prends à taxi »."],"answer":0},{"audio":"Je prends en bus.","question":"Esta frase tiene un error. ¿Cuál?","options":["Debería decir « je prends le bus ».","Debería decir « je prends à bus ».","Está correcta."],"answer":0}],"speaking":[{"situation":"Di « Yo tomo el metro cada mañana ».","expected":"Je prends le métro chaque matin."},{"situation":"Pregunta « Para ir a la Torre Eiffel, por favor ».","expected":"Pour aller à la Tour Eiffel, s'il vous plaît ?"},{"situation":"Pregunta si está lejos de aquí.","expected":"C'est loin d'ici ?"},{"situation":"Di « Tomo el taxi porque llueve ».","expected":"Je prends le taxi parce qu'il pleut."},{"situation":"Pregunta « ¿Debo cambiar de línea? ».","expected":"Je dois changer de ligne ?"}],"writing":[{"prompt":"Completa: « Je prends ______ métro. »","answer":"le"},{"prompt":"Completa: « Je prends ______ taxi. »","answer":"le"},{"prompt":"Ordena: « aller / pour / la gare / ? »","answer":"Pour aller à la gare ?"},{"prompt":"Ordena: « loin / c'est / d'ici / ? »","answer":"C'est loin d'ici ?"},{"prompt":"Corrige: « Je prends en bus. »","answer":"Je prends le bus."}]},"defiSteps":[{"serveur":"Bonjour ! Montez, s'il vous plaît. Quelle est votre destination ?","hint":"Da tu destino usando « Je voudrais aller à… ».","example":"Bonjour ! Je voudrais aller à la gare du Nord, s'il vous plaît."},{"serveur":"Très bien. On y va.","hint":"Pregunta la duración del trayecto.","example":"Quelle est la durée du trajet, s'il vous plaît ?"},{"serveur":"Environ 20 minutes selon le trafic.","hint":"Pregunta el tarif o precio aproximado.","example":"Et quel est le tarif approximatif ?"},{"serveur":"Entre 15 et 20 euros. Regardez le compteur.","hint":"Pide bajarte al llegar con « Arrêtez-vous ici ».","example":"Parfait. Arrêtez-vous ici, s'il vous plaît."},{"serveur":"Voilà, ça fait 17 euros. Bonne journée !","hint":"Paga y despídete con cortesía.","example":"Merci beaucoup. Voici 20 euros. Bonne journée !"}],"defiCriteria":["Saluda y usa fórmulas de cortesía apropiadas al contexto.","Emplea el vocabulario clave del día (Taxi & ville à pied).","Aplica la estructura gramatical del día correctamente.","Responde a las preguntas del interlocutor sin cambiar al español.","Pide aclaración o repetición si no entiende algo.","Cierra la interacción con una despedida adecuada."],"tutor":{"role":"chauffeur de taxi parisino; el alumno sube al taxi","opener_fr":"Bonjour ! Montez, montez ! Vous allez où aujourd'hui ?","opener_es":"¡Hola! ¡Suba, suba! ¿A dónde va hoy?","objectives":["Di a dónde vas (« Je vais à… »)","Pregunta cuánto cuesta o cuánto tarda","Paga y despídete"],"topic":"En taxi et en ville — moverse por la ciudad"},"meta":{"label":"Jour 10 · Taxi & ville à pied","headTitle":"Jour 10 · Taxi & ville à pied — Liberté","headDesc":"Jour 10 · Taxi & ville à pied: lección completa del programa Liberté.","week":2,"weekEmoji":"🚕","intro":"Bienvenue au Jour 10 ! Taxi & ville à pied. Respire, tu es prêt.","introSub":"Taxi & ville à pied.","clesSub":"Donner une adresse, demander le prix.","defiTitle":"Taxi & ville à pied","defiSubtitle":"Toma un taxi y llega a tu destino.","defiAvatar":"🚕"}}$rich$::jsonb)
